SET NAMES utf8mb4;

REPLACE INTO site_content (id, data) VALUES (1, '{"faq":[{"a":{"de":"Eine Vorschau mit 20 Bildern gibt es innerhalb von 48 Stunden. Die vollständige Galerie folgt nach etwa drei Wochen, der Film nach sechs Wochen.","tr":"48 saat içinde 20 karelik bir ön izleme gönderiyoruz. Tam galeri yaklaşık üç hafta, film ise altı hafta sonra hazır oluyor."},"q":{"de":"Wie schnell bekommen wir die Bilder?","tr":"Kareleri ne kadar sürede alıyoruz?"}},{"a":{"de":"In eurer privaten Galerie markiert ihr die Favoriten mit einem Herz und sendet die Auswahl mit einem Klick ab. Wir sehen sie sofort im Admin-Bereich – kein Excel, keine Dateinamen-Listen.","tr":"Özel galerinizde beğendiklerinizi kalp ile işaretleyip tek tıkla gönderiyorsunuz. Biz seçimi yönetim panelinde anında görüyoruz – Excel yok, dosya adı listesi yok."},"q":{"de":"Wie funktioniert die Bildauswahl fürs Album?","tr":"Albüm için fotoğraf seçimi nasıl oluyor?"}},{"a":{"de":"Für Paare, die ein Foto- oder Filmpaket gebucht haben, ja. Alle anderen können die Einladung für 79 € einmalig erstellen.","tr":"Foto veya film paketi alan çiftler için evet. Diğerleri davetiyeyi tek seferlik 79 €\'ya oluşturabiliyor."},"q":{"de":"Ist die digitale Einladung wirklich kostenlos?","tr":"Dijital davetiye gerçekten ücretsiz mi?"}},{"a":{"de":"Alle Galerien liegen passwortgeschützt auf Servern in der EU. Bilder werden nur mit eurer Freigabe veröffentlicht, Analytics läuft nur nach Einwilligung.","tr":"Tüm galeriler AB\'deki sunucularda parola korumalı tutuluyor. Kareler yalnızca sizin onayınızla yayınlanıyor, analiz araçları yalnızca izinle çalışıyor."},"q":{"de":"Wie sind die Daten geschützt?","tr":"Veriler nasıl korunuyor?"}},{"a":{"de":"Wir sind in einem Netzwerk mit sechs Kolleginnen und Kollegen aus der Region. Im Notfall steht innerhalb von 24 Stunden ein gleichwertiger Ersatz bereit – vertraglich zugesichert.","tr":"Bölgedeki altı meslektaşımızla bir ağ içindeyiz. Acil durumda 24 saat içinde eşdeğer bir ekip devreye giriyor – sözleşmeyle güvence altında."},"q":{"de":"Was passiert bei Krankheit?","tr":"Hastalık durumunda ne oluyor?"}}],"hero":{"text":{"de":"Dokumentarische Hochzeitsfotografie und Film in Krumbach und Bayerisch-Schwaben. Ruhig gearbeitet, ehrlich erzählt – und pünktlich geliefert.","tr":"Krumbach ve Bavyera-Suabya’da belgesel tarzda düğün fotoğrafçılığı ve video. Sakin çalışılmış, dürüst anlatılmış – ve zamanında teslim edilmiş."},"title":{"de":"Der Tag vergeht.\\nDie Bilder bleiben.","tr":"Gün geçer.\\nKareler kalır."},"eyebrow":{"de":"Hochzeitsfotografie & Film · Krumbach","tr":"Düğün fotoğrafçılığı & film · Krumbach"}},"about":{"body":{"de":["Ich bin über den Journalismus zur Hochzeitsfotografie gekommen. Zehn Jahre lang habe ich für Zeitungen und Magazine fotografiert – Menschen, die nicht wussten, dass sie fotografiert werden, und Situationen, die man nicht wiederholen kann. Genau diese Haltung habe ich mitgenommen.","Eine Hochzeit ist kein Fotoshooting mit Feier drumherum. Sie ist ein Tag, an dem hunderte kleine Dinge passieren, die niemand geplant hat: der Bruder, der beim Einzug heimlich Tränen wegwischt. Die Großmutter, die zum ersten Mal seit Jahren tanzt. Die Braut, die zwei Minuten allein im Nebenzimmer steht.","Deshalb arbeite ich leise. Ich stelle keine Szenen nach, ich unterbreche keine Reden für ein besseres Foto und ich rufe niemanden zurück, weil das Licht gerade schöner ist. Was ich mache: den Tag vorher so planen, dass die schönen Momente überhaupt Platz haben.","Bei größeren Hochzeiten bin ich nicht allein. Mein Team besteht aus zwei festen Kolleginnen für Zweitkamera und Film – wir arbeiten seit vier Jahren zusammen und brauchen keine Absprachen mehr während der Feier."],"tr":["Düğün fotoğrafçılığına gazetecilikten geldim. On yıl boyunca gazeteler ve dergiler için çektim – fotoğraflandığını bilmeyen insanlar ve tekrar edilemeyecek anlar. Bu yaklaşımı olduğu gibi getirdim.","Düğün, etrafında kutlama olan bir fotoğraf çekimi değildir. Kimsenin planlamadığı yüzlerce küçük şeyin yaşandığı bir gündür: girişte gizlice gözyaşını silen abi. Yıllar sonra ilk kez dans eden anneanne. Yan odada iki dakika tek başına duran gelin.","Bu yüzden sessiz çalışıyorum. Sahne yeniden kurdurmuyorum, daha iyi bir kare için konuşmaları bölmüyorum ve ışık güzelleşti diye kimseyi geri çağırmıyorum. Yaptığım şey: günü önceden öyle planlamak ki o güzel anlara yer kalsın.","Büyük düğünlerde yalnız değilim. Ekibimde ikinci kamera ve film için iki sabit meslektaşım var – dört yıldır birlikte çalışıyoruz, düğün sırasında artık konuşmamıza bile gerek kalmıyor."]},"gear":{"de":["Zwei Vollformat-Gehäuse pro Person, jeweils mit Doppel-Kartenslot","Festbrennweiten 35 / 50 / 85 mm, f/1.4","Entfesselte Blitze für dunkle Säle","Funkmikrofone für Trauung und Reden","Doppelte Sicherung noch am Hochzeitsabend, Archiv für 24 Monate"],"tr":["Kişi başı iki full frame gövde, her biri çift kart yuvalı","35 / 50 / 85 mm f/1.4 sabit lensler","Karanlık salonlar için harici flaşlar","Nikah ve konuşmalar için telsiz mikrofonlar","Düğün akşamı çift yedekleme, 24 ay arşiv"]},"lead":{"de":"Fotograf und Filmemacher aus Stuttgart. Seit 2016 Hochzeiten – vorher zehn Jahre Reportage.","tr":"Stuttgart\'tan fotoğrafçı ve film yapımcısı. 2016\'dan beri düğün – öncesinde on yıl foto muhabirliği."},"name":"Julian Roth","values":[{"d":{"de":"Keine Kommandos, keine Unterbrechungen. Ihr merkt uns kaum – das sieht man später auf den Bildern.","tr":"Komut yok, kesinti yok. Bizi neredeyse fark etmiyorsunuz – bu sonradan karelerde görülüyor."},"t":{"de":"Leise statt laut","tr":"Sessiz, gürültüsüz"}},{"d":{"de":"Ich sage vorher, was zeitlich geht und was nicht. Lieber ein realistischer Plan als ein enttäuschter Abend.","tr":"Zaman olarak neyin mümkün olduğunu önceden söylüyorum. Hayal kırıklığı yerine gerçekçi bir plan."},"t":{"de":"Ehrlich statt geschönt","tr":"Dürüst, süslemesiz"}},{"d":{"de":"Vorschau in 48 Stunden, Galerie in drei Wochen, Film in sechs. Vertraglich zugesichert.","tr":"48 saatte ön izleme, üç haftada galeri, altı haftada film. Sözleşmeyle garanti."},"t":{"de":"Pünktlich statt irgendwann","tr":"Zamanında"}},{"d":{"de":"Deutsch und Türkisch – bei Familien, in denen beide Sprachen gesprochen werden, macht das den Tag deutlich entspannter.","tr":"Almanca ve Türkçe – iki dilin konuşulduğu ailelerde bu, günü ciddi şekilde rahatlatıyor."},"t":{"de":"Zweisprachig","tr":"İki dilli"}}],"gearTitle":{"de":"Technik","tr":"Ekipman"},"valuesTitle":{"de":"Wie ich arbeite","tr":"Nasıl çalışıyorum"}},"legal":{"agb":{"note":"**Hinweis:** Vorlage für die Demo-Version. Vor dem Livegang anwaltlich prüfen lassen.","title":"Allgemeine Geschäftsbedingungen","sections":[{"body":"Diese Bedingungen gelten für alle Foto- und Filmaufträge sowie für digitale Produkte (Online-Galerie, digitale Hochzeitseinladung) von {legalName}, {street}, {zip} {city}.","heading":"§ 1 Geltungsbereich"},{"body":"Der Vertrag kommt mit schriftlicher Auftragsbestätigung zustande. Der Termin gilt erst mit Eingang der Anzahlung in Höhe von 30 % der Auftragssumme als reserviert. Die Restzahlung ist spätestens 14 Tage nach der Veranstaltung fällig.","heading":"§ 2 Vertragsschluss und Reservierung"},{"body":"Der Umfang ergibt sich aus dem gebuchten Paket. Die Auswahl und Bearbeitung der Bilder erfolgt nach künstlerischem Ermessen der Fotografin bzw. des Fotografen. Ein Anspruch auf unbearbeitete Rohdaten besteht nicht.","heading":"§ 3 Leistungsumfang"},{"body":"- Vorschau mit rund 20 Bildern innerhalb von 48 Stunden\\n- Vollständige Online-Galerie innerhalb von drei Wochen\\n- Hochzeitsfilm innerhalb von sechs Wochen","heading":"§ 4 Liefer- und Bearbeitungszeiten"},{"body":"Die Auftraggeber erhalten ein einfaches, zeitlich und räumlich unbeschränktes Nutzungsrecht für private Zwecke einschließlich der Veröffentlichung in sozialen Netzwerken. Eine kommerzielle Nutzung oder Weitergabe an Dritte zu gewerblichen Zwecken bedarf einer gesonderten Vereinbarung. Das Urheberrecht verbleibt bei der Urheberin bzw. dem Urheber.","heading":"§ 5 Nutzungsrechte"},{"body":"Eine Veröffentlichung der Aufnahmen zu Referenzzwecken erfolgt ausschließlich nach gesonderter schriftlicher Einwilligung der abgebildeten Personen. Die Einwilligung ist freiwillig und jederzeit widerrufbar.","heading":"§ 6 Veröffentlichung durch uns"},{"body":"Bei Rücktritt der Auftraggeber bis 180 Tage vor dem Termin wird die Anzahlung einbehalten. Bei späterem Rücktritt werden 50 % der Auftragssumme fällig, ab 30 Tagen vor dem Termin 80 %. Bei Krankheit oder höherer Gewalt auf unserer Seite stellen wir eine gleichwertige Vertretung aus unserem Netzwerk; ist dies nicht möglich, werden bereits geleistete Zahlungen vollständig erstattet. Weitergehende Ansprüche sind ausgeschlossen.","heading":"§ 7 Rücktritt und Ausfall"},{"body":"Die private Galerie ist passwortgeschützt und steht für 24 Monate zur Verfügung. Die Weitergabe der Zugangsdaten an Familie und Gäste ist gestattet, eine öffentliche Verbreitung des Links nicht.","heading":"§ 8 Online-Galerie"},{"body":"Die digitale Einladung ist für Kundinnen und Kunden mit gebuchtem Foto- oder Filmpaket kostenfrei. Für alle übrigen Nutzer beträgt der Preis einmalig 79 € inkl. MwSt.; die Einladungsseite bleibt zwölf Monate nach dem Hochzeitsdatum erreichbar. Für die eingegebenen Inhalte sind die erstellenden Personen verantwortlich. Es besteht kein Anspruch auf ununterbrochene Verfügbarkeit; wir bemühen uns um eine Erreichbarkeit von 99 % im Jahresmittel.","heading":"§ 9 Digitale Hochzeitseinladung"},{"body":"Verbraucher haben bei Fernabsatzverträgen ein 14-tägiges Widerrufsrecht. Bei Dienstleistungen zu einem bestimmten Termin (Veranstaltungsfotografie, § 312g Abs. 2 Nr. 9 BGB) besteht kein Widerrufsrecht. Bei digitalen Inhalten erlischt das Widerrufsrecht mit ausdrücklicher Zustimmung zum vorzeitigen Beginn der Ausführung.","heading":"§ 10 Widerrufsrecht"},{"body":"Es gilt deutsches Recht. Sollten einzelne Bestimmungen unwirksam sein, bleibt die Wirksamkeit der übrigen Bestimmungen unberührt.","heading":"§ 11 Schlussbestimmungen"}]},"impressum":{"note":"**Hinweis:** Dieser Text ist eine Vorlage für die Demo-Version und ersetzt keine Rechtsberatung. Vor dem Livegang sind die Angaben durch die Betreiberin bzw. den Betreiber zu prüfen und zu ergänzen.","title":"Impressum","sections":[{"body":"{legalName}\\n{owner}\\n{street}\\n{zip} {city}","heading":"Angaben gemäß § 5 DDG"},{"body":"Telefon: {phone}\\nE-Mail: {email}","heading":"Kontakt"},{"body":"Umsatzsteuer-Identifikationsnummer gemäß § 27 a Umsatzsteuergesetz:\\nDE 123 456 789","heading":"Umsatzsteuer-ID"},{"body":"Fotograf (Bundesrepublik Deutschland)\\nZuständige Kammer: Handwerkskammer Region Stuttgart","heading":"Berufsbezeichnung"},{"body":"{owner}\\n{street}, {zip} {city}","heading":"Redaktionell verantwortlich"},{"body":"Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) bereit: [ec.europa.eu/consumers/odr](https://ec.europa.eu/consumers/odr/). Unsere E-Mail-Adresse finden Sie oben im Impressum.","heading":"EU-Streitschlichtung"},{"body":"Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.","heading":"Verbraucherstreitbeilegung"},{"body":"Alle auf dieser Website gezeigten Aufnahmen sind Platzhalter der Demo-Version. In der Live-Version stammen sämtliche Bilder von {owner} und werden ausschließlich mit schriftlicher Einwilligung der abgebildeten Personen veröffentlicht.","heading":"Bildnachweis"},{"body":"Als Diensteanbieter sind wir für eigene Inhalte auf diesen Seiten nach den allgemeinen Gesetzen verantwortlich. Für Inhalte externer Links ist stets der jeweilige Anbieter verantwortlich. Zum Zeitpunkt der Verlinkung waren keine Rechtsverstöße erkennbar.","heading":"Haftung für Inhalte und Links"}]},"datenschutz":{"note":"**Hinweis:** Dieser Text ist eine Vorlage für die Demo-Version. Vor dem Livegang ist er an die tatsächlich eingesetzten Dienste anzupassen und juristisch zu prüfen.","title":"Datenschutzerklärung","sections":[{"body":"{legalName}, {owner}, {street}, {zip} {city}\\nE-Mail: {email} · Telefon: {phone}","heading":"1. Verantwortlicher"},{"body":"Diese Website wird bei einem Anbieter mit Serverstandort in der Europäischen Union betrieben. Beim Aufruf der Seite werden technisch notwendige Daten (IP-Adresse in gekürzter Form, Datum und Uhrzeit, aufgerufene Seite, Browsertyp) in Server-Logfiles verarbeitet. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO (berechtigtes Interesse am sicheren und stabilen Betrieb). Die Logfiles werden nach spätestens 30 Tagen gelöscht. Mit dem Hoster besteht ein Auftragsverarbeitungsvertrag nach Art. 28 DSGVO.","heading":"2. Hosting und Server-Logfiles"},{"body":"Alle Schriftarten werden lokal von unserem eigenen Server geladen. Es besteht dabei **keine Verbindung zu Servern von Google**. Karteninhalte (Google Maps) werden nicht automatisch eingebunden – erst wenn Sie aktiv auf einen Kartenlink klicken, verlassen Sie diese Website.","heading":"3. Schriften und externe Inhalte"},{"body":"Technisch notwendige Speicherungen (z. B. Ihre Cookie-Entscheidung, der Zugang zur privaten Galerie) erfolgen auf Grundlage von § 25 Abs. 2 TDDDG. Statistik- und Marketing-Cookies werden ausschließlich nach Ihrer ausdrücklichen Einwilligung gesetzt (Art. 6 Abs. 1 lit. a DSGVO, § 25 Abs. 1 TDDDG). Ihre Einwilligung können Sie jederzeit mit Wirkung für die Zukunft widerrufen:\\n\\n{{consent}}","heading":"4. Cookies und Einwilligung"},{"body":"Wenn Sie uns über das Formular, per E-Mail, Telefon oder WhatsApp kontaktieren, verarbeiten wir die von Ihnen angegebenen Daten zur Bearbeitung Ihrer Anfrage. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO (vorvertragliche Maßnahmen) bzw. lit. f DSGVO. Anfragen ohne anschließenden Vertragsschluss löschen wir nach spätestens zwölf Monaten; bei Vertragsschluss gelten die handels- und steuerrechtlichen Aufbewahrungsfristen von bis zu zehn Jahren.","heading":"5. Kontaktformular und Anfragen"},{"body":"Die Online-Galerie ist ausschließlich mit Zugangscode und Passwort erreichbar und über die Datei `robots.txt` sowie ein `noindex`-Meta-Tag von Suchmaschinen ausgeschlossen. Gespeichert werden der Zugriffszeitpunkt sowie die von Ihnen markierte Bildauswahl. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO (Vertragserfüllung). Galerien werden spätestens 24 Monate nach der Hochzeit gelöscht, sofern nichts anderes vereinbart wurde.","heading":"6. Private Kundengalerie"},{"body":"Beim Erstellen einer Einladung verarbeiten wir die von Ihnen eingegebenen Angaben (Namen, Datum, Ort, Text, optional ein Bild) zur Bereitstellung der Einladungsseite. Rückmeldungen Ihrer Gäste (Name, Zu- oder Absage, Personenzahl, optionale Nachricht) werden zur Weitergabe an Sie als Gastgeberin bzw. Gastgeber gespeichert. Verantwortlich für die Inhalte der jeweiligen Einladung sind die erstellenden Paare; wir handeln insoweit als Auftragsverarbeiter. Einladungsseiten sind nicht indexierbar und werden zwölf Monate nach dem Hochzeitsdatum gelöscht.","heading":"7. Digitale Hochzeitseinladung"},{"body":"Sofern Sie eingewilligt haben, nutzen wir Google Analytics 4 mit aktivierter IP-Anonymisierung. Anbieter ist Google Ireland Limited. Eine Übermittlung in Drittländer erfolgt auf Grundlage der EU-Standardvertragsklauseln und des EU-US Data Privacy Framework. Ohne Ihre Einwilligung wird kein Analytics-Skript geladen.","heading":"8. Reichweitenmessung"},{"body":"- Auskunft über die zu Ihnen gespeicherten Daten (Art. 15 DSGVO)\\n- Berichtigung unrichtiger Daten (Art. 16 DSGVO)\\n- Löschung (Art. 17 DSGVO) und Einschränkung der Verarbeitung (Art. 18 DSGVO)\\n- Datenübertragbarkeit (Art. 20 DSGVO)\\n- Widerspruch gegen Verarbeitungen auf Grundlage berechtigter Interessen (Art. 21 DSGVO)\\n- Widerruf erteilter Einwilligungen mit Wirkung für die Zukunft (Art. 7 Abs. 3 DSGVO)\\n- Beschwerde bei einer Aufsichtsbehörde (Art. 77 DSGVO)\\n\\nZuständige Aufsichtsbehörde: Der Landesbeauftragte für den Datenschutz und die Informationsfreiheit Baden-Württemberg, Lautenschlagerstraße 20, 70173 Stuttgart.","heading":"9. Ihre Rechte"},{"body":"Aufnahmen von Hochzeiten werden ausschließlich mit gesonderter schriftlicher Einwilligung der abgebildeten Personen veröffentlicht. Diese Einwilligung ist freiwillig, unabhängig vom Fotoauftrag und jederzeit mit Wirkung für die Zukunft widerrufbar.","heading":"10. Bildrechte und Veröffentlichung"}]}},"posts":[{"faq":[{"a":{"de":"Für Samstage zwischen Mai und September sind zwölf bis achtzehn Monate üblich. Unter der Woche und in der Nebensaison reichen oft sechs Monate.","tr":"Mayıs–Eylül arası cumartesiler için on iki ila on sekiz ay normaldir. Hafta içi ve sezon dışında çoğu zaman altı ay yeterli oluyor."},"q":{"de":"Wie früh sollten wir den Hochzeitsfotografen buchen?","tr":"Düğün fotoğrafçısını ne kadar önceden ayırtmalıyız?"}},{"a":{"de":"Ab etwa 120 Gästen oder wenn sich Braut und Bräutigam getrennt vorbereiten, lohnt sich die zweite Kamera fast immer. Bei kleinen Feiern ist sie meist verzichtbar.","tr":"Yaklaşık 120 kişiden sonra ya da gelin ve damat ayrı hazırlanıyorsa ikinci kamera neredeyse her zaman işe yarıyor. Küçük kutlamalarda genelde gerekmiyor."},"q":{"de":"Ist ein zweiter Fotograf notwendig?","tr":"İkinci bir fotoğrafçı gerekli mi?"}}],"body":{"de":["Die meisten Paare buchen ihren Hochzeitsfotografen nach zwei Kriterien: Bildsprache und Preis. Beides ist wichtig, aber beides sagt wenig darüber aus, wie der Tag tatsächlich ablaufen wird. Die folgenden Fragen kosten euch ein Gespräch und ersparen euch im Zweifel eine Enttäuschung.","## 1. Wer fotografiert tatsächlich bei uns?","Bei größeren Studios ist die Person im Erstgespräch nicht immer die Person am Hochzeitstag. Lasst euch den Namen geben und fragt nach einer vollständigen Hochzeit von genau dieser Person – nicht nach einer Best-of-Auswahl aus mehreren Aufträgen.","## 2. Dürfen wir eine komplette Hochzeit sehen?","Eine Galerie mit 30 Höhepunkten kann jeder zusammenstellen. Interessant ist, wie die zweihundert Bilder dazwischen aussehen: die Rede, die niemand geplant hat, der dunkle Saal um 22 Uhr, die Familienaufstellung mit 40 Personen.","## 3. Was passiert bei Krankheit oder Ausfall?","Ein seriöser Vertrag regelt das schriftlich: Ersatz aus einem Netzwerk innerhalb einer festen Frist oder vollständige Rückerstattung. Eine mündliche Zusage ist an dieser Stelle zu wenig.","## 4. Wie lange dauert die Lieferung – und was steht im Vertrag?","„Ein paar Wochen“ ist keine Frist. Fragt nach konkreten Zahlen für Vorschau, vollständige Galerie und Film, und danach, ob diese Fristen vertraglich zugesichert sind.","## 5. Wie viele Bilder bekommen wir, und in welcher Form?","Wichtig ist weniger die Anzahl als das Format: Bekommt ihr die Bilder in voller Auflösung zum Herunterladen? Gibt es eine Online-Galerie? Dürft ihr die Bilder privat frei nutzen?","## 6. Wart ihr schon einmal in unserer Location?","Wer die Location kennt, weiß, wo um 18 Uhr noch Licht steht und welche Wege wie lange dauern. Wer sie nicht kennt, sollte vorher hinfahren – fragt, ob das eingeplant ist.","## 7. Was passiert mit unseren Bildern?","Veröffentlichung auf Website und Social Media darf nur mit gesonderter, freiwilliger Einwilligung erfolgen. Diese Einwilligung muss unabhängig vom Fotoauftrag sein und jederzeit widerrufbar bleiben.","Wenn eine Fotografin oder ein Fotograf auf alle sieben Fragen ruhig und konkret antwortet, habt ihr die wichtigste Information schon: Da arbeitet jemand, der seinen Ablauf kennt."],"tr":["Çiftlerin çoğu düğün fotoğrafçısını iki ölçüte göre seçiyor: görsel tarz ve fiyat. İkisi de önemli, ama ikisi de günün gerçekte nasıl geçeceği hakkında pek bir şey söylemiyor. Aşağıdaki sorular size bir görüşmeye mal olur, karşılığında olası bir hayal kırıklığını önler.","## 1. Bizim düğünümüzde gerçekte kim çekecek?","Büyük stüdyolarda ilk görüşmedeki kişi, düğün günü gelen kişi olmayabiliyor. İsmi net alın ve tam olarak o kişinin çektiği eksiksiz bir düğün isteyin – farklı işlerden derlenmiş bir seçki değil.","## 2. Eksiksiz bir düğün görebilir miyiz?","Otuz karelik bir seçkiyi herkes hazırlayabilir. Asıl mesele aradaki iki yüz karenin nasıl olduğu: kimsenin planlamadığı konuşma, gece 22\'de karanlık salon, kırk kişilik aile fotoğrafı.","## 3. Hastalık ya da aksilik durumunda ne oluyor?","Ciddi bir sözleşme bunu yazılı düzenler: belirli bir süre içinde ağdan eşdeğer ekip ya da tam iade. Bu konuda sözlü güvence yeterli değil.","## 4. Teslim ne kadar sürüyor – ve sözleşmede ne yazıyor?","\\"Birkaç hafta\\" bir süre değildir. Ön izleme, tam galeri ve film için somut sayılar isteyin; bu sürelerin sözleşmeyle güvence altına alınıp alınmadığını sorun.","## 5. Kaç kare alıyoruz ve hangi biçimde?","Sayıdan çok biçim önemli: Kareleri tam çözünürlükte indirebiliyor musunuz? Online galeri var mı? Kareleri özel kullanımda serbestçe kullanabiliyor musunuz?","## 6. Bizim mekânımızda daha önce çekim yaptınız mı?","Mekânı bilen kişi, saat 18\'de ışığın nerede durduğunu ve hangi geçişin ne kadar sürdüğünü bilir. Bilmeyen önceden gidip görmeli – bunun planlanıp planlanmadığını sorun.","## 7. Karelerimize ne olacak?","Web sitesinde ve sosyal medyada yayın, yalnızca ayrı ve gönüllü bir izinle yapılabilir. Bu izin fotoğraf işinden bağımsız olmalı ve her zaman geri alınabilmeli.","Bir fotoğrafçı bu yedi sorunun hepsine sakin ve somut cevap veriyorsa, en önemli bilgiyi zaten almışsınız demektir: karşınızda akışını bilen biri var."]},"date":"2026-05-18","seed":"lum-blog-fragen","slug":"hochzeitsfotograf-finden-sieben-fragen","title":{"de":"Hochzeitsfotograf finden: 7 Fragen, die ihr vor der Buchung stellen solltet","tr":"Düğün fotoğrafçısı seçerken sormanız gereken 7 soru"},"excerpt":{"de":"Der Preis allein sagt wenig. Diese sieben Fragen zeigen euch in zehn Minuten, ob jemand zu eurem Tag passt – und decken die Punkte auf, über die später am häufigsten gestritten wird.","tr":"Fiyat tek başına bir şey söylemez. Bu yedi soru, on dakikada size uygun olup olmadığını gösterir – ve sonradan en çok tartışma çıkan noktaları önceden ortaya koyar."},"citySlug":"stuttgart","uploads":[]},{"faq":[{"a":{"de":"30 bis 45 Minuten reichen für die Bilder, die später wirklich verwendet werden. Längere Shootings werden für die meisten Paare anstrengend, ohne dass die Ergebnisse besser werden.","tr":"Sonradan gerçekten kullanılan kareler için 30–45 dakika yeterli. Daha uzun çekimler çoğu çift için yorucu oluyor ve sonuç daha iyi olmuyor."},"q":{"de":"Wie lange dauert ein Paarshooting?","tr":"Çift çekimi ne kadar sürer?"}},{"a":{"de":"Vorher, direkt im Anschluss an den Sektempfang. Dann sind alle Gäste anwesend und die Aufstellung dauert halb so lang.","tr":"Önce, karşılamanın hemen ardından. O anda tüm misafirler orada olur ve dizilim yarı sürede tamamlanır."},"q":{"de":"Sollen die Gruppenbilder vor oder nach dem Essen sein?","tr":"Grup fotoğrafları yemekten önce mi sonra mı?"}}],"body":{"de":["Fast jede Hochzeit, bei der am Ende Zeit fehlt, hat dasselbe Problem: Der Ablauf wurde nach den Wünschen der Location geplant, nicht nach dem Licht. Dabei ist die goldene Stunde der einzige Punkt im Tagesablauf, den niemand verschieben kann.","## Wann ist die goldene Stunde?","Sie beginnt etwa eine Stunde vor Sonnenuntergang und dauert je nach Jahreszeit 30 bis 50 Minuten. Im Juni in Baden-Württemberg heißt das ungefähr 20:15 Uhr, Ende September bereits 18:30 Uhr. Ein Unterschied von fast zwei Stunden – geplant wird der Tag aber oft mit demselben Schema.","## Ein Ablauf, der aufgeht","Getting Ready ab drei Stunden vor der Trauung, mit Puffer für die Anfahrt. Trauung. Danach Sektempfang und Gruppenbilder, solange alle Gäste noch beisammen sind – das dauert mit 40 Personen etwa 25 Minuten, nicht zehn.","Der entscheidende Block: 30 bis 45 Minuten Paarshooting, gelegt auf die goldene Stunde. Das bedeutet, dass das Abendessen entweder davor endet oder danach beginnt. Beides funktioniert – nur mitten hinein sollte es nicht fallen.","## Die drei häufigsten Fehler","Erstens: Gruppenbilder erst nach dem Essen. Dann sind einige Gäste schon draußen, andere nicht mehr ganz bei der Sache. Zweitens: kein Puffer zwischen Trauung und Empfang – zehn Minuten Verspätung verschieben den ganzen Abend. Drittens: das Paarshooting auf die Mittagszeit legen, weil dann gerade Zeit ist. Hartes Mittagslicht ist die schwierigste Situation des Tages.","## Was tun, wenn es regnet?","Ein guter Plan hat für jeden Außenpunkt eine Innenalternative, die vorher angesehen wurde. Regen ist kein Problem, wenn er eingeplant ist – überdachte Eingänge, Fensterlicht und Schirme ergeben oft die ungewöhnlicheren Bilder."],"tr":["Sonunda zaman yetmeyen düğünlerin neredeyse hepsinde aynı sorun var: akış, mekânın istekleri üzerine kurulmuş, ışığın üzerine değil. Oysa altın saat, günün kimsenin erteleyemeyeceği tek noktası.","## Altın saat ne zaman?","Gün batımından yaklaşık bir saat önce başlar ve mevsime göre 30–50 dakika sürer. Baden-Württemberg\'de haziranda bu aşağı yukarı 20:15, eylül sonunda ise 18:30 demek. Neredeyse iki saatlik fark – ama gün çoğu zaman aynı şablonla planlanıyor.","## İşleyen bir akış","Hazırlık, nikahtan üç saat önce başlar, yol için pay bırakılır. Nikah. Ardından karşılama ve grup fotoğrafları – henüz herkes bir aradayken. Kırk kişiyle bu on değil, yaklaşık 25 dakika sürer.","Belirleyici blok: altın saate denk getirilmiş 30–45 dakikalık çift çekimi. Bu da akşam yemeğinin ya ondan önce bitmesi ya da sonra başlaması demek. İkisi de olur – yeter ki tam ortasına denk gelmesin.","## En sık yapılan üç hata","Birincisi: grup fotoğraflarını yemekten sonraya bırakmak. O saatte bir kısım misafir dışarıda, bir kısmının aklı başka yerde olur. İkincisi: nikah ile karşılama arasına pay koymamak – on dakikalık gecikme bütün akşamı kaydırır. Üçüncüsü: çift çekimini öğlene almak, çünkü \\"o saatte boşluk var\\". Sert öğle ışığı günün en zor koşuludur.","## Yağmur yağarsa?","İyi bir planda her açık hava noktasının, önceden görülmüş bir kapalı alternatifi vardır. Yağmur, planlandığı sürece sorun değildir – kapalı girişler, pencere ışığı ve şemsiyeler çoğu zaman daha sıra dışı kareler verir."]},"date":"2026-06-24","seed":"lum-blog-zeitplan","slug":"hochzeit-zeitplan-licht","title":{"de":"Der Zeitplan, der wirklich funktioniert – und warum das Licht ihn bestimmt","tr":"Gerçekten işe yarayan düğün akışı – ve neden ışık belirler"},"excerpt":{"de":"Die schönsten Paarbilder entstehen in einem Zeitfenster von 40 Minuten. Wer den Tag darum herum plant, braucht keine Bilder nachzustellen. So sieht ein realistischer Ablauf aus.","tr":"En güzel çift kareleri 40 dakikalık bir aralıkta çıkıyor. Günü onun etrafına kuran çift, hiçbir kareyi yeniden kurgulamak zorunda kalmıyor. Gerçekçi bir akış şöyle görünür."},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Nein. Beide Termine lassen sich in einem Paket zusammenfassen; das ist in der Regel günstiger als zwei Einzelbuchungen und sorgt dafür, dass beide Abende dieselbe Bildsprache haben.","tr":"Hayır. İki tarih tek pakette birleştirilebilir; bu genelde iki ayrı anlaşmadan daha uygun oluyor ve iki akşamın da aynı görsel dilde olmasını sağlıyor."},"q":{"de":"Braucht man für Kına-Nacht und Hochzeit zwei getrennte Buchungen?","tr":"Kına gecesi ve düğün için iki ayrı anlaşma mı gerekiyor?"}},{"a":{"de":"Bei 150 Gästen sind 30 bis 45 Minuten realistisch. Plant diesen Punkt fest ein, sonst verschiebt er den ganzen Abend.","tr":"150 misafirde 30–45 dakika gerçekçi. Bu maddeyi akışa sabit koyun, yoksa bütün akşamı kaydırıyor."},"q":{"de":"Wie lange dauert das Goldanstecken?","tr":"Takı takma ne kadar sürer?"}}],"body":{"de":["Eine deutsch-türkische Hochzeit ist selten ein Tag. Häufig sind es zwei oder drei: die Kına-Nacht, das Standesamt und die große Feier – manchmal über zwei Wochenenden verteilt, manchmal an aufeinanderfolgenden Abenden. Für die Fotografie heißt das vor allem: vorher klären, was wann stattfindet und wer welche Rolle hat.","## Die Kına-Nacht ist kein Vorprogramm","Der Henna-Abend ist emotional oft der intensivste Teil der ganzen Feier. Der Moment, in dem der Braut die Hand geschlossen wird, während die Schwiegermutter die Goldmünze hineinlegt, dauert vielleicht 40 Sekunden. Wer in dieser Zeit den Objektivwechsel macht, hat ihn verpasst.","Praktisch bedeutet das: zwei Kameras, kein Wechsel während des Rituals, und vorher wissen, aus welcher Richtung die Braut hereingeführt wird. Das Licht ist meist warm und schwach – lichtstarke Festbrennweiten sind hier keine Spielerei, sondern Voraussetzung.","## Standesamt und Nikah trennen","Viele Paare haben eine standesamtliche Trauung und zusätzlich einen Nikah. Beide brauchen Zeit im Plan, auch wenn der eine Termin nur 20 Minuten dauert. Fragt vorher, ob im Trauzimmer fotografiert werden darf und wo genau ihr stehen dürft – die Regeln unterscheiden sich von Ort zu Ort.","## Der Einzug und das Geldanstecken","Bei der großen Feier sind zwei Programmpunkte gesetzt: der Einzug des Paares und das Anstecken von Gold und Geld. Letzteres kann bei großen Familien 45 Minuten dauern und ist für die Gäste einer der wichtigsten Momente – im Zeitplan wird er trotzdem regelmäßig vergessen.","## Zweisprachigkeit ist Arbeitserleichterung","Wenn eine Großmutter nur Türkisch spricht und der Trauzeuge nur Deutsch, entscheidet die Verständigung darüber, wie entspannt die Gruppenbilder werden. Ein Team, das beide Sprachen spricht, spart bei 40 Personen leicht zehn Minuten – und die Bilder sehen entsprechend gelöster aus.","## Was in den Zeitplan gehört","Kına-Ritual, Einzug, Nikah beziehungsweise Trauung, Goldanstecken, Eröffnungstanz, Halay. Für jeden dieser Punkte eine Uhrzeit und eine grobe Dauer – mehr braucht es nicht, damit der Tag ohne Kommandos abläuft."],"tr":["Alman-Türk düğünü nadiren tek bir gündür. Çoğu zaman iki ya da üç: kına gecesi, nikah dairesi ve büyük düğün – kimi zaman iki hafta sonuna yayılır, kimi zaman ardışık akşamlarda olur. Fotoğraf açısından bunun anlamı şu: neyin ne zaman olduğu ve kimin hangi rolde olduğu önceden netleşmeli.","## Kına gecesi bir ön program değildir","Kına, duygusal olarak çoğu zaman tüm kutlamanın en yoğun bölümüdür. Kaynananın altını avuca koyup gelinin elinin kapatıldığı an belki 40 saniye sürer. O sırada lens değiştiren, o anı kaçırmıştır.","Pratikte bu şu demek: iki kamera, ritüel sırasında değişiklik yok ve gelinin hangi yönden getirileceğini önceden bilmek. Işık genelde sıcak ve zayıftır – geniş diyaframlı sabit lensler burada bir lüks değil, gereklilik.","## Nikah dairesi ile dinî nikahı ayırın","Birçok çiftin hem resmî nikahı hem de dinî nikahı oluyor. İkisi de planda yer kaplamalı, biri yalnızca 20 dakika sürse bile. Nikah salonunda fotoğraf çekilip çekilemeyeceğini ve tam olarak nerede durabileceğinizi önceden sorun – kurallar yere göre değişiyor.","## Giriş ve takı takma","Büyük düğünde iki program maddesi kesindir: çiftin girişi ve altın/para takma. İkincisi kalabalık ailelerde 45 dakikayı bulabilir ve misafirler için en önemli anlardan biridir – buna rağmen akış planında düzenli olarak unutulur.","## İki dillilik işi kolaylaştırır","Bir anneanne yalnızca Türkçe, sağdıç yalnızca Almanca konuşuyorsa, grup fotoğraflarının ne kadar rahat geçeceğini anlaşma belirler. İki dili de konuşan bir ekip, kırk kişilik dizilimde rahatlıkla on dakika kazandırır – kareler de o oranda rahat çıkar.","## Akışta mutlaka olması gerekenler","Kına ritüeli, giriş, nikah, takı takma, ilk dans, halay. Bu maddelerin her biri için bir saat ve kabaca bir süre – günün komut verilmeden akması için fazlası gerekmiyor."]},"date":"2026-07-30","seed":"lum-blog-kina","slug":"deutsch-tuerkische-hochzeit-fotografieren","title":{"de":"Deutsch-türkische Hochzeit: Was beim Fotografieren wirklich zählt","tr":"Alman-Türk düğünü: Fotoğrafta gerçekten önemli olan ne?"},"excerpt":{"de":"Zwei Feiern, zwei Familien, oft zwei Sprachen. Wer den Ablauf einer Kına-Nacht und eines Nikah kennt, verpasst die Momente nicht, auf die es ankommt – hier die Punkte, die im Zeitplan stehen müssen.","tr":"İki kutlama, iki aile, çoğu zaman iki dil. Kına gecesinin ve nikahın akışını bilen, önemli anları kaçırmaz – akışta mutlaka yer alması gereken noktalar."},"citySlug":"stuttgart"}],"stats":{"years":"9","rating":"4,9 ★","delivery":"3","weddings":"180+"},"addons":[{"name":{"de":"Zweiter Fotograf (ganzer Tag)","tr":"İkinci fotoğrafçı (tüm gün)"},"price":"+ 450 €"},{"name":{"de":"Henna-Abend / Verlobung (3 Std.)","tr":"Kına gecesi / nişan (3 saat)"},"price":"+ 490 €"},{"name":{"de":"After-Wedding-Shooting (2 Std.)","tr":"After-Wedding çekimi (2 saat)"},"price":"+ 390 €"},{"name":{"de":"Fotoalbum 30×30 cm, 40 Seiten","tr":"Fotoğraf albümü 30×30 cm, 40 sayfa"},"price":"+ 590 €"},{"name":{"de":"Digitale Einladung mit RSVP","tr":"RSVP\'li dijital davetiye"},"price":"79 €"},{"name":{"de":"Anfahrt über 60 km","tr":"60 km üzeri yol"},"price":"0,40 €/km"}],"cities":[{"slug":"guenzburg","name":"Günzburg","kreis":{"de":"Landkreis Günzburg","tr":"Günzburg ilçesi"},"drive":{"de":"rund 25 Minuten","tr":"yaklaşık 25 dakika"},"lead":{"de":"Hochzeitsfotograf und Videograf in Günzburg – die nächste Stadt von Krumbach aus, und die mit der geschlossensten Altstadt der Region.","tr":"Günzburg’da düğün fotoğrafçısı ve videografı – Krumbach’a en yakın şehir ve bölgenin en bütün kalmış eski kenti."},"body":{"de":["Günzburg ist für uns Nachbarschaft. Wir sind in einer knappen halben Stunde da, und wir kennen die Stadt nicht von einer Ortsbesichtigung, sondern von Hochzeiten zu jeder Jahreszeit. Das merkt man an Kleinigkeiten: dass der Marktplatz zum Schloss hin ansteigt und Gruppenbilder deshalb von unten besser aussehen als von oben. Dass die Frauenkirche von Dominikus Zimmermann innen ein Licht hat, mit dem man ohne Blitz arbeiten kann, wenn man weiß, wo man steht.","Die Altstadt ist kompakt genug, dass Trauung, Sektempfang und Paarshooting ohne Umziehen der ganzen Gesellschaft funktionieren. Das ist mehr wert, als es klingt: Jede Fahrt zwischen zwei Orten kostet vierzig Minuten Stimmung. Wer am Nachmittag heiratet, hat vom Schlossplatz aus bis in den frühen Abend weiches Licht; danach wird es in den Gassen schnell dunkel, und wir gehen an die Günz oder in Richtung Stadtpark."],"tr":["Günzburg bizim için komşu demek. Yarım saatten kısa sürede oradayız ve şehri bir keşif gezisinden değil, her mevsimden düğünlerden tanıyoruz. Bu, küçük şeylerde belli oluyor: meydanın saraya doğru yükseldiğini, bu yüzden toplu fotoğrafların aşağıdan daha iyi durduğunu bilmek gibi. Ya da Dominikus Zimmermann’ın Frauenkirche’sinin içinde, nerede duracağınızı bilirseniz flaşsız çalışılabilecek bir ışık olduğunu.","Eski kent, nikâh, kokteyl ve çift çekimi bütün topluluğu taşımadan yapılabilecek kadar derli toplu. Bu kulağa geldiğinden daha değerli: iki yer arasındaki her yolculuk kırk dakikalık keyif götürüyor. Öğleden sonra evlenenler saray meydanından akşamın ilk saatlerine kadar yumuşak ışık buluyor; sonrasında dar sokaklar hızla kararıyor, biz de Günz kıyısına ya da şehir parkına doğru geçiyoruz."]},"spots":[{"name":"Marktplatz und Schlossplatz","note":{"de":"Der Aufstieg zum Schloss gibt Tiefe. Vormittags liegt die Westseite im Schatten – dann lieber die Häuserzeile gegenüber.","tr":"Saraya çıkan eğim derinlik veriyor. Sabahları batı yüzü gölgede – o saatte karşıdaki sıra evler daha iyi."}},{"name":"Frauenkirche","note":{"de":"Heller Rokoko-Innenraum, der ohne zusätzliches Licht auskommt. Fotografieren nur nach Absprache mit der Pfarrei.","tr":"Ek ışık gerektirmeyen aydınlık rokoko iç mekân. Çekim yalnızca kilise idaresiyle konuşulduktan sonra."}},{"name":"Günzufer und Auwald","note":{"de":"Grün und ruhig, fünf Gehminuten aus der Altstadt. Die letzte Stunde vor Sonnenuntergang gehört hierher.","tr":"Yeşil ve sakin, eski kentten beş dakika yürüyüş. Gün batımından önceki son saat buraya ait."}}],"faq":[{"q":{"de":"Kommt ihr auch für eine kleine Trauung ohne Feier?","tr":"Kutlamasız küçük bir nikâh için de gelir misiniz?"},"a":{"de":"Ja. Für Günzburg gibt es dafür eine kurze Begleitung von zwei Stunden – Trauung, Gratulation, ein Rundgang durch die Altstadt. Anfahrt berechnen wir im Landkreis Günzburg nicht.","tr":"Evet. Günzburg için iki saatlik kısa bir eşlik var – nikâh, tebrikler, eski kentte bir tur. Günzburg ilçesi içinde yol ücreti almıyoruz."}},{"q":{"de":"Lohnt sich Legoland als Kulisse?","tr":"Legoland fon olarak işe yarar mı?"},"a":{"de":"Für Hochzeitsbilder eher nicht – es ist ein Freizeitpark mit eigenen Regeln und vielen Menschen im Bild. Wenn Familie mit Kindern angereist ist, planen wir es lieber als eigenen Programmpunkt am Folgetag ein.","tr":"Düğün fotoğrafı için pek değil – kendi kuralları ve karede çok insan olan bir eğlence parkı. Çocuklu aile geldiyse onu ertesi güne ayrı bir program olarak koymayı tercih ediyoruz."}}],"venues":[],"neighbours":["ulm","neu-ulm","augsburg","memmingen"]},{"slug":"ulm","name":"Ulm","kreis":{"de":"Stadtkreis Ulm, Baden-Württemberg","tr":"Ulm şehri, Baden-Württemberg"},"drive":{"de":"rund 40 Minuten","tr":"yaklaşık 40 dakika"},"lead":{"de":"Hochzeitsfotograf und Videograf in Ulm – Münster, Fischerviertel und Donau auf engem Raum, mit dem schwierigsten und schönsten Licht der Region.","tr":"Ulm’da düğün fotoğrafçısı ve videografı – Münster, Fischerviertel ve Tuna dar bir alanda; bölgenin hem en zor hem en güzel ışığıyla."},"body":{"de":["Ulm ist die Stadt in unserem Umkreis, in der man am meisten falsch machen kann. Der Münsterplatz ist weit und hell, und um die Mittagszeit steht die Sonne so, dass Gesichter unter den Augen dunkel werden. Wir legen Paarbilder deshalb selten dorthin, sondern in das Fischerviertel: schmale Gassen, Fachwerk, die Blau in mehreren Armen, und Schatten, der weich ist statt hart. Wer trotzdem das Münster im Bild haben will, bekommt es von der Herdbrücke oder von der Donaupromenade aus – mit Abstand, und ohne dass der Turm oben abgeschnitten ist.","Das zweite Thema in Ulm ist Publikum. Die Altstadt ist an Samstagnachmittagen voll, und ein Brautpaar bleibt dort nicht unbemerkt. Manche Paare genießen das, andere werden still davon. Wir sprechen das vorher an und planen entsprechend: entweder früh am Morgen, wenn die Gassen leer sind, oder in den Randlagen an der Donau, wo man zu zweit sein kann, ohne aus der Stadt zu fahren."],"tr":["Ulm, çevremizde en çok hata yapılabilecek şehir. Münster meydanı geniş ve parlak; öğle saatlerinde güneş öyle bir açıda ki gözlerin altı kararıyor. Bu yüzden çift fotoğraflarını oraya nadiren koyuyoruz, Fischerviertel’i tercih ediyoruz: dar sokaklar, ahşap cumbalar, birkaç kola ayrılan Blau deresi ve sert değil yumuşak gölge. Yine de karede Münster isteyenler onu Herdbrücke’den ya da Tuna kıyısından alıyor – mesafeyle ve kulenin tepesi kesilmeden.","Ulm’un ikinci konusu kalabalık. Eski kent cumartesi öğleden sonraları dolu ve gelin damat orada fark edilmeden kalmıyor. Bazı çiftler bundan keyif alıyor, bazıları sesini kesiyor. Bunu önceden konuşup ona göre planlıyoruz: ya sokaklar boşken sabah erken, ya da şehirden çıkmadan baş başa kalınabilen Tuna kıyısındaki kenar noktalarda."]},"spots":[{"name":"Fischerviertel","note":{"de":"Enge Gassen an der Blau, weiches Streiflicht bis in den Nachmittag. Kopfsteinpflaster – hohe Absätze vorher bedenken.","tr":"Blau kıyısında dar sokaklar, öğleden sonraya kadar yumuşak yan ışık. Arnavut kaldırımı – yüksek topuğu önceden düşünün."}},{"name":"Donaupromenade und Metzgerturm","note":{"de":"Weite und Wasser, das Münster im Hintergrund. Am späten Abend das beste Licht der Stadt.","tr":"Genişlik ve su, arkada Münster. Akşamın geç saatinde şehrin en iyi ışığı."}},{"name":"Münsterplatz","note":{"de":"Groß und repräsentativ, aber hart im Mittagslicht und selten leer. Für Gruppenbilder besser am frühen Vormittag.","tr":"Büyük ve gösterişli ama öğle ışığında sert ve nadiren boş. Toplu fotoğraf için sabahın erken saati daha iyi."}}],"faq":[{"q":{"de":"Braucht man in Ulm eine Genehmigung zum Fotografieren?","tr":"Ulm’da fotoğraf için izin gerekiyor mu?"},"a":{"de":"Für ein Paar mit Fotograf im öffentlichen Raum in aller Regel nicht. Anders wird es bei Aufbauten, Drohne oder größeren Gruppen, die einen Weg blockieren – das klären wir vorher mit der Stadt, damit am Hochzeitstag niemand diskutiert.","tr":"Kamusal alanda fotoğrafçıyla bir çift için kural olarak gerekmiyor. Ekipman kurulumu, drone ya da yolu kapatacak büyük gruplar başka konu – onu düğün günü kimse tartışmasın diye önceden belediyeyle hallediyoruz."}},{"q":{"de":"Ulm oder Neu-Ulm – wo sollen wir fotografieren?","tr":"Ulm mu Neu-Ulm mu – nerede çekilelim?"},"a":{"de":"Die Donau trennt beide, die Brücke braucht vier Minuten zu Fuß. Wir nutzen oft beides: die Altstadtseite für Enge und Fachwerk, die Neu-Ulmer Seite für Weite und den Blick zurück aufs Münster.","tr":"İkisini Tuna ayırıyor, köprü yürüyerek dört dakika. Çoğu zaman ikisini birden kullanıyoruz: dar sokak ve ahşap için eski kent tarafı, genişlik ve Münster’e dönük manzara için Neu-Ulm tarafı."}}],"venues":[],"neighbours":["neu-ulm","guenzburg","memmingen","augsburg"]},{"slug":"neu-ulm","name":"Neu-Ulm","kreis":{"de":"Landkreis Neu-Ulm, Bayern","tr":"Neu-Ulm ilçesi, Bavyera"},"drive":{"de":"rund 40 Minuten","tr":"yaklaşık 40 dakika"},"lead":{"de":"Hochzeitsfotograf und Videograf in Neu-Ulm – die ruhige Seite der Donau, mit Platz für Gruppenbilder und dem Münster als Hintergrund.","tr":"Neu-Ulm’da düğün fotoğrafçısı ve videografı – Tuna’nın sakin yakası; toplu fotoğraf için yer ve arka planda Münster."},"body":{"de":["Neu-Ulm wird unterschätzt, weil die berühmte Stadt gegenüber liegt. Fotografisch ist genau das der Vorteil: Von hier aus hat man das Ulmer Münster im Bild, ohne im Gedränge davor zu stehen. Die Donaupromenade ist breit, das Ufer ist offen, und eine Hochzeitsgesellschaft von fünfzig Personen findet Platz, ohne dass jemand auf der Straße steht.","Der Glacis-Park ist der zweite Grund, warum wir gern hierherkommen. Alter Baumbestand, gepflegte Wege, im Sommer Schatten und im Herbst Farbe – und er ist groß genug, dass zwei Hochzeiten am selben Tag sich nicht begegnen. Für Paare, die es unaufgeregt mögen, ist Neu-Ulm oft die bessere Wahl als die Altstadt gegenüber, und die Bilder sagen trotzdem eindeutig, wo sie entstanden sind."],"tr":["Neu-Ulm hafife alınıyor, çünkü ünlü şehir tam karşıda. Fotoğraf açısından asıl avantaj bu: buradan Ulm Münster’i karede oluyor, önündeki kalabalığın içinde durmadan. Tuna kıyısı geniş, sahil açık; elli kişilik bir düğün topluluğu kimse yola taşmadan yerleşiyor.","Glacis Parkı buraya gelmeyi sevmemizin ikinci sebebi. Yaşlı ağaçlar, bakımlı yollar, yazın gölge, sonbaharda renk – ve aynı gün iki düğünün karşılaşmayacağı kadar büyük. Sakin seven çiftler için Neu-Ulm çoğu zaman karşıdaki eski kentten daha iyi bir tercih; fotoğraflar yine de nerede çekildiğini net söylüyor."]},"spots":[{"name":"Donauufer mit Blick aufs Münster","note":{"de":"Die Postkarte, ohne das Gedränge der anderen Seite. Am schönsten in der Stunde vor Sonnenuntergang.","tr":"Kartpostal manzarası, karşı yakanın kalabalığı olmadan. En güzeli gün batımından önceki saat."}},{"name":"Glacis-Park","note":{"de":"Alter Baumbestand, weicher Schatten auch mittags. Bei Regen tragen die Wege besser als Wiesenwege.","tr":"Yaşlı ağaçlar, öğlen bile yumuşak gölge. Yağmurda yollar çayır patikalarından daha iyi taşıyor."}},{"name":"Edwin-Scharff-Haus und Umfeld","note":{"de":"Klare Architektur direkt am Wasser – gute Gegenposition zum Fachwerk auf der Ulmer Seite.","tr":"Su kenarında yalın mimari – Ulm tarafındaki ahşap dokuya iyi bir karşıtlık."}}],"faq":[{"q":{"de":"Wir feiern in Ulm, aber die Trauung ist in Neu-Ulm. Geht das?","tr":"Kutlama Ulm’da, nikâh Neu-Ulm’da. Olur mu?"},"a":{"de":"Das ist der Normalfall und kostet kaum Zeit – über die Brücke sind es wenige Minuten. Wir planen den Wechsel so, dass er in die Fahrt der Gesellschaft fällt und nicht extra Programm wird.","tr":"Bu olağan durum ve neredeyse hiç zaman almıyor – köprüden birkaç dakika. Geçişi topluluğun zaten yapacağı yolculuğa denk getiriyoruz, ayrı bir program olmasın diye."}},{"q":{"de":"Gibt es Platz für ein Gruppenbild mit allen Gästen?","tr":"Bütün misafirlerle toplu fotoğraf için yer var mı?"},"a":{"de":"Ja, und das ist hier leichter als in den meisten Altstädten. Am Donauufer und im Glacis-Park stehen achtzig Personen, ohne dass wir jemanden auf eine Mauer stellen müssen.","tr":"Evet, üstelik çoğu eski kentten daha kolay. Tuna kıyısında ve Glacis Parkı’nda seksen kişi, kimseyi duvara çıkarmadan yerleşiyor."}}],"venues":[],"neighbours":["ulm","guenzburg","memmingen","augsburg"]},{"slug":"memmingen","name":"Memmingen","kreis":{"de":"Kreisfreie Stadt, Tor zum Allgäu","tr":"Bağımsız şehir, Allgäu’ya açılan kapı"},"drive":{"de":"rund 40 Minuten","tr":"yaklaşık 40 dakika"},"lead":{"de":"Hochzeitsfotograf und Videograf in Memmingen – eine Altstadt, die auch bei Regen funktioniert, und der kürzeste Weg ins Allgäu.","tr":"Memmingen’de düğün fotoğrafçısı ve videografı – yağmurda da işleyen bir eski kent ve Allgäu’ya en kısa yol."},"body":{"de":["Memmingen hat etwas, das im Sommer niemanden interessiert und im November alles rettet: Arkaden. Am Steuerhaus und rund um den Marktplatz kann man trocken stehen und trotzdem draußen sein. Wir haben hier Hochzeiten fotografiert, an denen es durchgehend geregnet hat, und die Bilder sehen nicht nach Notlösung aus. Für ein Datum im Spätherbst oder Vorfrühling ist das ein echtes Argument.","Der zweite Grund ist die Geschlossenheit. Der Marktplatz mit Rathaus und Steuerhaus, das Siebendächerhaus an der Stadtbach-Ecke, die Gassen dazwischen – das liegt alles in Gehweite, und es wirkt aus jedem Winkel wie eine Kulisse, die jemand aufgebaut hat. Wer von Memmingen ins Allgäu weiterfährt, hat außerdem nach zwanzig Minuten Wiesen und Berge im Rücken, wenn es das Paar in die Landschaft zieht."],"tr":["Memmingen’de yazın kimsenin umursamadığı, kasımda ise her şeyi kurtaran bir şey var: revaklar. Steuerhaus’ta ve meydanın çevresinde kuru durup yine de dışarıda olabiliyorsunuz. Burada baştan sona yağmur yağan düğünler çektik ve fotoğraflar mecburiyetten çekilmiş gibi durmuyor. Geç sonbahar ya da erken ilkbahar tarihi için bu gerçek bir gerekçe.","İkinci sebep bütünlük. Belediye ve Steuerhaus’lu meydan, dere köşesindeki Siebendächerhaus, aradaki sokaklar – hepsi yürüme mesafesinde ve her açıdan biri özellikle kurmuş gibi duruyor. Memmingen’den Allgäu’ya devam edenler, çift kırsala çekiliyorsa yirmi dakika sonra arkalarında çayır ve dağ buluyor."]},"spots":[{"name":"Marktplatz mit Steuerhaus","note":{"de":"Die Arkaden sind der Regenplan. Auch bei Sonne guter Schatten, wenn der Platz zu hell wird.","tr":"Revaklar yağmur planı. Güneşte de, meydan fazla parlarken iyi bir gölge."}},{"name":"Siebendächerhaus am Stadtbach","note":{"de":"Unverwechselbar und klein – gut für zwei Personen, nicht für die ganze Gesellschaft.","tr":"Ayırt edici ama küçük – iki kişilik, bütün topluluk için değil."}},{"name":"Stadtmauer und Westertor","note":{"de":"Ruhiger als der Marktplatz, mit Grün davor. Am späten Nachmittag steht die Sonne günstig.","tr":"Meydandan sakin, önünde yeşillik. Öğleden sonranın geç saatinde güneş uygun açıda."}}],"faq":[{"q":{"de":"Was, wenn es an unserem Termin regnet?","tr":"Tarihimizde yağmur yağarsa ne olacak?"},"a":{"de":"In Memmingen ist das die Stadt mit dem besten Plan B im Umkreis. Wir gehen unter die Arkaden am Marktplatz, arbeiten mit den Torbögen und dem nassen Pflaster – Regen wird dann Teil der Bilder statt ihr Gegner.","tr":"Memmingen bu konuda çevredeki en iyi B planına sahip şehir. Meydandaki revakların altına geçiyor, kemerlerle ve ıslak taşla çalışıyoruz – yağmur o zaman fotoğrafların düşmanı değil parçası oluyor."}},{"q":{"de":"Fahrt ihr von Memmingen aus weiter ins Allgäu?","tr":"Memmingen’den Allgäu’ya devam eder misiniz?"},"a":{"de":"Gern. Für Paare, die Berge im Bild haben möchten, planen wir ein Zeitfenster von rund zwei Stunden ein – Hin- und Rückweg mitgerechnet. Das lohnt sich nur bei gutem Wetter, und wir entscheiden es am Morgen des Hochzeitstags gemeinsam.","tr":"Memnuniyetle. Karede dağ isteyen çiftler için gidiş dönüş dahil yaklaşık iki saatlik bir pencere ayırıyoruz. Bu yalnızca hava iyiyse değer; kararı düğün sabahı birlikte veriyoruz."}}],"venues":[],"neighbours":["ulm","neu-ulm","guenzburg","friedrichshafen"]},{"slug":"augsburg","name":"Augsburg","kreis":{"de":"Kreisfreie Stadt, Bayerisch-Schwaben","tr":"Bağımsız şehir, Bavyera-Suabya"},"drive":{"de":"rund 50 Minuten","tr":"yaklaşık 50 dakika"},"lead":{"de":"Hochzeitsfotograf und Videograf in Augsburg – Renaissance im großen Maßstab, und die einzige Stadt der Region, in der Wasser Weltkulturerbe ist.","tr":"Augsburg’da düğün fotoğrafçısı ve videografı – büyük ölçekte Rönesans ve bölgede suyu dünya mirası olan tek şehir."},"body":{"de":["Augsburg ist die repräsentativste Stadt in unserem Umkreis. Die Maximilianstraße ist breit wie ein Platz, das Rathaus mit dem Goldenen Saal ist keine Kulisse, sondern ein Bauwerk, das im Bild Gewicht hat, und die Fuggerei ist eine Straße für sich – die älteste bestehende Sozialsiedlung der Welt, mit Backsteinfassaden und Ruhe mitten in der Stadt. Wer Bilder möchte, die nach Anlass aussehen, findet hier mehr davon als irgendwo sonst zwischen Ulm und München.","Diese Größe hat eine Kehrseite: Augsburg braucht Zeit. Zwischen Perlachturm, Fuggerei und den Wasserläufen im Lechviertel liegen Wege, die man nicht in zwanzig Minuten macht, und die Innenstadt ist auf breite Straßen gebaut, nicht auf kurze. Wir planen für Augsburg deshalb ein größeres Fenster ein oder legen uns vorher auf zwei Orte fest, statt vier halb zu sehen. Für die Wasserläufe gilt: schmale Kanäle, historische Brunnen, und am Vormittag deutlich weniger Menschen als nachmittags."],"tr":["Augsburg çevremizdeki en gösterişli şehir. Maximilianstraße bir meydan kadar geniş; Altın Salon’lu belediye binası bir fon değil, karede ağırlığı olan bir yapı; Fuggerei ise kendi başına bir sokak – dünyanın ayakta kalmış en eski sosyal konut yerleşimi, tuğla cepheler ve şehrin ortasında sessizlik. Anlamına yakışan fotoğraflar isteyen, Ulm ile Münih arasında bunun en fazlasını burada bulur.","Bu büyüklüğün bir de öbür yüzü var: Augsburg zaman istiyor. Perlach Kulesi, Fuggerei ve Lech mahallesindeki su yolları arasında yirmi dakikada alınmayacak mesafeler var; şehir merkezi kısa yollar üzerine değil geniş caddeler üzerine kurulmuş. Bu yüzden Augsburg için ya daha geniş bir pencere ayırıyoruz ya da dördünü yarım görmektense önceden iki yere karar veriyoruz. Su yolları için şunu bilin: dar kanallar, tarihî çeşmeler ve sabahları öğleden sonraya göre belirgin biçimde az insan."]},"spots":[{"name":"Fuggerei","note":{"de":"Backstein, Grün, kaum Durchgangsverkehr. Zutritt und Fotografieren nur nach Anmeldung – wir kümmern uns darum.","tr":"Tuğla, yeşil, neredeyse hiç geçiş trafiği yok. Giriş ve çekim yalnız randevuyla – onu biz hallediyoruz."}},{"name":"Rathausplatz und Perlachturm","note":{"de":"Große Fläche für große Gesellschaften. Mittags hart – dann in die Arkaden der Maximilianstraße ausweichen.","tr":"Kalabalık topluluklar için geniş alan. Öğlen sert – o saatte Maximilianstraße revaklarına geçmek gerekiyor."}},{"name":"Lechviertel und Wasserläufe","note":{"de":"Schmale Kanäle und alte Handwerkerhäuser, ruhiger als das Zentrum. Vormittags am leersten.","tr":"Dar kanallar ve eski zanaatkâr evleri, merkezden sakin. En boş hâli sabah."}}],"faq":[{"q":{"de":"Kann man in der Fuggerei heiraten oder fotografieren?","tr":"Fuggerei’de evlenilir ya da fotoğraf çekilir mi?"},"a":{"de":"Fotografieren ist nach Anmeldung möglich, es ist aber ein bewohntes Quartier und kein Fotostudio – wir arbeiten dort leise und ohne Aufbauten. Die Anmeldung übernehmen wir rechtzeitig vor dem Termin.","tr":"Çekim randevuyla mümkün ama orası bir stüdyo değil, insanların yaşadığı bir mahalle – sessiz ve kurulum yapmadan çalışıyoruz. Randevuyu tarihten önce biz alıyoruz."}},{"q":{"de":"Berechnet ihr für Augsburg Anfahrt?","tr":"Augsburg için yol ücreti alıyor musunuz?"},"a":{"de":"Nein. Augsburg liegt in dem Umkreis, den wir ohne Anfahrtskosten abdecken. Erst ab etwa 80 Kilometern kommt eine Pauschale dazu, und die steht dann im Angebot, bevor irgendetwas unterschrieben wird.","tr":"Hayır. Augsburg yol ücreti almadığımız çevrede kalıyor. Yaklaşık 80 kilometreden sonra sabit bir tutar ekleniyor ve o da hiçbir şey imzalanmadan önce teklifte yazıyor."}}],"venues":[],"neighbours":["guenzburg","ulm","muenchen","neu-ulm"]},{"slug":"muenchen","name":"München","kreis":{"de":"Landeshauptstadt Bayern","tr":"Bavyera eyalet başkenti"},"drive":{"de":"rund 1 Stunde 15","tr":"yaklaşık 1 saat 15"},"lead":{"de":"Hochzeitsfotograf und Videograf in München – für Paare, die uns aus Schwaben mitnehmen, und für Feiern, die den Aufwand wert sind.","tr":"Münih’te düğün fotoğrafçısı ve videografı – bizi Suabya’dan yanında götüren çiftler ve bu emeğe değen kutlamalar için."},"body":{"de":["München ist nicht unsere Nachbarschaft, und wir tun nicht so. Wir kommen hierher, weil Paare uns mitnehmen, die wir aus der Region kennen, oder weil eine Familie zwischen Schwaben und der Landeshauptstadt verteilt ist. Das ist ein anderer Auftrag als eine Hochzeit zwanzig Minuten von zu Hause: Wir reisen am Vorabend an, wenn der Tag früh beginnt, und wir planen mit mehr Puffer, weil in München jede Fahrt zwischen zwei Orten länger dauert, als der Kartendienst sagt.","Fotografisch ist die Stadt reich und streng zugleich. Der Schlosspark Nymphenburg und der Englische Garten sind großartig und öffentlich – mit allem, was dazugehört: Läufer im Hintergrund, andere Hochzeitsgesellschaften, und für gewerbliche Aufnahmen teils eigene Regeln. Die Arkaden am Odeonsplatz und die Isarauen sind unsere ruhigeren Gegenvorschläge. Was in München immer funktioniert, ist der frühe Morgen: um sieben gehört die Stadt für eine Stunde niemandem."],"tr":["Münih bizim mahallemiz değil ve öyleymiş gibi yapmıyoruz. Buraya, bölgeden tanıdığımız çiftler bizi yanında götürdüğü ya da bir aile Suabya ile başkent arasında dağıldığı için geliyoruz. Bu, evden yirmi dakikadaki bir düğünden başka bir iş: gün erken başlıyorsa bir akşam önceden geliyoruz ve daha geniş pay bırakıyoruz, çünkü Münih’te iki yer arası her yolculuk harita uygulamasının dediğinden uzun sürüyor.","Fotoğraf açısından şehir hem zengin hem katı. Nymphenburg Sarayı parkı ve İngiliz Bahçesi muhteşem ve halka açık – beraberinde geleniyle: arka planda koşucular, başka düğün toplulukları ve ticari çekim için yer yer ayrı kurallar. Odeonsplatz revakları ve Isar kıyıları bizim daha sakin karşı önerilerimiz. Münih’te her zaman işleyen şey sabahın erken saati: yedide şehir bir saatliğine kimsenin değil."]},"spots":[{"name":"Schlosspark Nymphenburg","note":{"de":"Weite Achsen und Wasser. Für gewerbliche Aufnahmen gelten eigene Regeln – vorher klären, nicht vor Ort diskutieren.","tr":"Geniş akslar ve su. Ticari çekimin ayrı kuralları var – yerinde tartışmak yerine önceden halledin."}},{"name":"Odeonsplatz und Hofgarten","note":{"de":"Arkaden als Regen- und Mittagsplan, Symmetrie für ruhige Bilder. Früh am Morgen fast leer.","tr":"Yağmur ve öğlen planı olarak revaklar, sakin kareler için simetri. Sabah erken neredeyse boş."}},{"name":"Isarauen","note":{"de":"Kies, Wasser und Bäume statt Architektur – der Gegenpol, wenn die Stadt zu viel wird.","tr":"Mimari yerine çakıl, su ve ağaç – şehir fazla geldiğinde karşı kutup."}}],"faq":[{"q":{"de":"Was kostet die Anfahrt nach München?","tr":"Münih’e yol ücreti ne kadar?"},"a":{"de":"Ab etwa 80 Kilometern kommt eine Anfahrtspauschale dazu; für München nennen wir sie im Angebot konkret, zusammen mit einer Übernachtung, falls der Tag vor acht Uhr beginnt oder nach Mitternacht endet. Nichts davon taucht später als Überraschung auf der Rechnung auf.","tr":"Yaklaşık 80 kilometreden sonra sabit bir yol ücreti ekleniyor; Münih için bunu teklifte açıkça yazıyoruz, gün sekizden önce başlıyor ya da gece yarısından sonra bitiyorsa konaklamayla birlikte. Hiçbiri sonradan faturada sürpriz olarak çıkmıyor."}},{"q":{"de":"Lohnt es sich, uns von so weit zu buchen?","tr":"Bu kadar uzaktan bizi tutmak mantıklı mı?"},"a":{"de":"Ehrlich: nur, wenn die Bilder zu euch passen und nicht, weil wir günstiger wären. München hat gute Fotografen. Paare buchen uns von hier aus meist, weil sie uns aus der Familie oder von einer anderen Hochzeit kennen – und das ist ein guter Grund.","tr":"Dürüst olalım: yalnızca fotoğraflar size uyuyorsa; daha ucuz olduğumuz için değil. Münih’in iyi fotoğrafçıları var. Buradan bizi tutan çiftler çoğunlukla aileden ya da başka bir düğünden tanıyor – ve bu iyi bir sebep."}}],"venues":[],"neighbours":["augsburg","guenzburg","memmingen"]},{"slug":"stuttgart","name":"Stuttgart","kreis":{"de":"Landeshauptstadt Baden-Württemberg","tr":"Baden-Württemberg eyalet başkenti"},"drive":{"de":"rund 1 Stunde 30","tr":"yaklaşık 1 saat 30"},"lead":{"de":"Hochzeitsfotograf und Videograf in Stuttgart – die Richtung nach Westen, mit Weinbergen direkt über der Stadt.","tr":"Stuttgart’ta düğün fotoğrafçısı ve videografı – batı yönü; şehrin hemen üstünde bağlar."},"body":{"de":["Stuttgart ist von Krumbach aus die längste Fahrt nach Westen, und für viele deutsch-türkische Familien in unserem Umkreis die Stadt, in der die Verwandtschaft wohnt. Genau deshalb fahren wir sie: Wenn eine Hälfte der Familie aus Schwaben kommt und die andere aus dem Stuttgarter Raum, ist die Feier oft dort, und der Fotograf kommt mit.","Die Stadt liegt in einem Kessel, und das ist fotografisch ihr größter Vorteil. Innerhalb von zehn Minuten ist man aus dem Zentrum in den Weinbergen, mit Blick über die Dächer – eine Kombination, die keine andere Stadt in unserem Gebiet so anbietet. Unten am Schlossplatz ist es großstädtisch und um die Mittagszeit hart im Licht; oben ist es still, und die Sonne geht über den Reben unter. Wer beides will, sollte zwei Stunden dafür einplanen und nicht vierzig Minuten."],"tr":["Stuttgart, Krumbach’tan batıya en uzun yolculuk ve çevremizdeki birçok Türk-Alman ailesi için akrabaların yaşadığı şehir. Tam bu yüzden gidiyoruz: ailenin bir yarısı Suabya’dan, diğeri Stuttgart bölgesinden geliyorsa kutlama çoğu zaman orada oluyor, fotoğrafçı da geliyor.","Şehir bir çanağın içinde ve fotoğraf açısından en büyük avantajı bu. Merkezden on dakikada bağların içindesiniz, çatıların üzerine bakan bir manzarayla – bölgemizdeki başka hiçbir şehrin böyle sunmadığı bir birleşim. Aşağıda saray meydanı büyük şehir gibi ve öğlen ışığı sert; yukarısı sessiz ve güneş asmaların ardında batıyor. İkisini birden isteyen kırk dakika değil iki saat ayırmalı."]},"spots":[{"name":"Weinberge über der Stadt","note":{"de":"Blick über die Dächer, goldene Stunde ohne Publikum. Steile Wege – Schuhe zum Wechseln mitnehmen.","tr":"Çatıların üzerine manzara, seyircisiz altın saat. Dik yollar – değiştirmek için ayakkabı alın."}},{"name":"Schlossplatz und Altes Schloss","note":{"de":"Großstädtisch und repräsentativ, mittags hart. Bei Regen tragen die Arkaden.","tr":"Büyük şehir havası ve gösterişli, öğlen sert. Yağmurda revaklar iş görüyor."}},{"name":"Höhenpark Killesberg","note":{"de":"Weiches Abendlicht und Weitblick, ruhiger als das Zentrum.","tr":"Yumuşak akşam ışığı ve geniş manzara, merkezden sakin."}}],"faq":[{"q":{"de":"Ihr sitzt in Schwaben – warum Stuttgart?","tr":"Siz Suabya’dasınız – neden Stuttgart?"},"a":{"de":"Weil Familien selten an einem Ort wohnen. Wir fahren die Strecke regelmäßig für Paare, deren Verwandtschaft im Stuttgarter Raum lebt, und kennen die Stadt gut genug, um nicht am Hochzeitstag nach einem Platz zu suchen.","tr":"Çünkü aileler nadiren tek bir yerde oturuyor. Bu yolu, akrabaları Stuttgart bölgesinde yaşayan çiftler için düzenli olarak yapıyoruz ve şehri düğün günü yer aramayacak kadar tanıyoruz."}},{"q":{"de":"Kommt eine Übernachtung dazu?","tr":"Konaklama ekleniyor mu?"},"a":{"de":"Wenn die Feier bis in die Nacht geht, ja – wir fahren nach zwölf Stunden Arbeit keine anderthalb Stunden mehr im Dunkeln zurück. Das steht vorher im Angebot, nicht hinterher auf der Rechnung.","tr":"Kutlama gece geç saate kadar sürüyorsa evet – on iki saatlik işten sonra karanlıkta bir buçuk saat yol yapmıyoruz. Bu sonradan faturada değil, önceden teklifte yazıyor."}}],"venues":[],"neighbours":["ulm","muenchen","augsburg"]},{"slug":"friedrichshafen","name":"Friedrichshafen","kreis":{"de":"Bodenseekreis","tr":"Bodensee bölgesi"},"drive":{"de":"rund 1 Stunde 40","tr":"yaklaşık 1 saat 40"},"lead":{"de":"Hochzeitsfotograf und Videograf in Friedrichshafen – Bodensee, offener Horizont und ein Licht, das vom Wasser zurückkommt.","tr":"Friedrichshafen’de düğün fotoğrafçısı ve videografı – Bodensee, açık ufuk ve sudan geri gelen bir ışık."},"body":{"de":["Am See ist das Licht anders, und das ist keine Floskel. Wasser wirft zurück, was von oben kommt, und füllt Schatten unter Augen und Kinn – das macht Portraits am Ufer weicher als in der Stadt. Dafür gibt es keinen Schutz: An einem klaren Julimittag ist die Promenade gnadenlos, und bei Wind kämpft jede Frisur. Wir planen Bodensee-Termine deshalb um die Tageszeit herum, nicht um den Ort.","Friedrichshafen selbst ist nüchterner als die Postkartenorte am See, und wir mögen das. Die Uferpromenade ist lang und offen, der Blick geht bei gutem Wetter bis an die Schweizer Berge, und der Zeppelin über dem Wasser ist ein Motiv, das es sonst nirgends gibt – wenn er fliegt, warten wir kurz. Für Paare, die Weite wollen statt Kulisse, ist das der richtige Ort in dieser Richtung."],"tr":["Gölde ışık başka ve bu bir laf kalabalığı değil. Su, yukarıdan geleni geri yansıtıyor ve gözlerin, çenenin altındaki gölgeyi dolduruyor – bu, kıyıdaki portreleri şehirdekinden yumuşak yapıyor. Buna karşılık korunak yok: açık bir temmuz öğlesinde sahil acımasız, rüzgârda her saç mücadele veriyor. Bu yüzden Bodensee tarihlerini yere göre değil, günün saatine göre planlıyoruz.","Friedrichshafen’in kendisi göldeki kartpostal kasabalarından daha sade ve bunu seviyoruz. Sahil uzun ve açık, hava iyiyse manzara İsviçre dağlarına kadar gidiyor, suyun üstündeki zeplin ise başka hiçbir yerde olmayan bir kare – uçuyorsa biraz bekliyoruz. Fon değil genişlik isteyen çiftler için bu yöndeki doğru yer burası."]},"spots":[{"name":"Uferpromenade und Hafen","note":{"de":"Offener Horizont, weiches Licht vom Wasser. Mittags ungeschützt – lieber die letzten zwei Stunden vor Sonnenuntergang.","tr":"Açık ufuk, sudan gelen yumuşak ışık. Öğlen korunaksız – gün batımından önceki son iki saat daha iyi."}},{"name":"Schlosskirche am See","note":{"de":"Zwei Türme direkt am Wasser, gut aus der Ferne. Innen nur nach Absprache mit der Gemeinde.","tr":"Su kenarında iki kule, uzaktan iyi duruyor. İçerisi yalnız cemaatle konuşulduktan sonra."}},{"name":"Uferpark Richtung Manzell","note":{"de":"Bäume und Wiese als Windschutz, wenn es auf der Promenade zu böig wird.","tr":"Sahil fazla rüzgârlıysa siper olarak ağaç ve çayır."}}],"faq":[{"q":{"de":"Was, wenn es am See stürmt?","tr":"Gölde fırtına çıkarsa ne olur?"},"a":{"de":"Dann gehen wir vom offenen Ufer weg in den Uferpark oder in geschützte Innenhöfe. Wind ist am Bodensee kein Ausnahmefall, sondern eine Planungsgröße – wir schauen am Morgen auf die Vorhersage und verschieben eher die Uhrzeit als den Ort.","tr":"O zaman açık kıyıdan sahil parkına ya da korunaklı avlulara geçiyoruz. Bodensee’de rüzgâr istisna değil, planlama verisi – sabah tahmine bakıyor ve yeri değil saati kaydırıyoruz."}},{"q":{"de":"Bleibt ihr über Nacht?","tr":"Geceyi orada geçiriyor musunuz?"},"a":{"de":"Bei Terminen am Bodensee in der Regel ja. Die Rückfahrt dauert fast zwei Stunden, und die letzten Bilder des Abends sind oft die besten – die wollen wir nicht wegen der Uhrzeit auslassen.","tr":"Bodensee tarihlerinde genelde evet. Dönüş neredeyse iki saat ve akşamın son kareleri çoğu zaman en iyileri – onları saat yüzünden atlamak istemiyoruz."}}],"venues":[],"neighbours":["memmingen","bregenz","st-gallen"]},{"slug":"bregenz","name":"Bregenz","kreis":{"de":"Vorarlberg, Österreich","tr":"Vorarlberg, Avusturya"},"drive":{"de":"rund 2 Stunden","tr":"yaklaşık 2 saat"},"lead":{"de":"Hochzeitsfotograf und Videograf in Bregenz – wo der Bodensee an den Berg stößt, mit Aussicht vom Pfänder über drei Länder.","tr":"Bregenz’de düğün fotoğrafçısı ve videografı – Bodensee’nin dağa dayandığı yer; Pfänder’den üç ülkeye bakan manzara."},"body":{"de":["Bregenz ist der einzige Ort in unserem Gebiet, an dem See und Berg direkt aneinanderstoßen. Vom Pfänder aus sieht man bei klarer Sicht über den Bodensee bis nach Deutschland und in die Schweiz – ein Bild, das kein anderer Ort auf dieser Liste hergibt. Der Weg nach oben geht mit der Seilbahn, und das ist Teil der Planung: Fahrzeiten, Betriebszeiten und eine Warteschlange an einem schönen Sonntag.","Unten ist Bregenz zweigeteilt. Die Seepromenade mit der Seebühne ist offen und modern, die Oberstadt mit dem Martinsturm ist eng, alt und deutlich ruhiger. Wir kombinieren das gern: eine Stunde oben in den Gassen, eine am Wasser. Was Paare aus Deutschland bedenken sollten: Bregenz liegt in Österreich. Für uns heißt das eine Auslandsanfahrt und eine andere Rechnungsstellung – beides klären wir vorher schriftlich, damit am Ende keine Frage offen ist."],"tr":["Bregenz, bölgemizde göl ile dağın doğrudan buluştuğu tek yer. Pfänder’den hava açıkken Bodensee’nin ötesinde Almanya ve İsviçre görünüyor – bu listedeki başka hiçbir yerin vermediği bir kare. Yukarı çıkış teleferikle ve bu planın parçası: sefer saatleri, çalışma saatleri ve güzel bir pazar günü kuyruk.","Aşağıda Bregenz ikiye ayrılıyor. Sahne’li göl sahili açık ve modern; Martinsturm’lu yukarı şehir dar, eski ve belirgin biçimde sakin. İkisini birleştirmeyi seviyoruz: bir saat yukarıda sokaklarda, bir saat su kenarında. Almanya’dan gelen çiftlerin bilmesi gereken: Bregenz Avusturya’da. Bizim için bu, yurt dışı yolculuğu ve farklı bir faturalandırma demek – ikisini de sonunda soru kalmasın diye önceden yazılı olarak netleştiriyoruz."]},"spots":[{"name":"Pfänder","note":{"de":"Blick über den ganzen See. Seilbahnzeiten prüfen – bei Nebel im Tal ist oben oft Sonne, umgekehrt aber auch.","tr":"Bütün göle bakan manzara. Teleferik saatlerine bakın – vadide sis varken yukarısı çoğu zaman güneşli, tersi de olabiliyor."}},{"name":"Seepromenade und Seebühne","note":{"de":"Weite und Wasser, modern. Während der Festspiele im Sommer voll und teils gesperrt.","tr":"Genişlik ve su, modern. Yaz festivali sırasında kalabalık ve yer yer kapalı."}},{"name":"Oberstadt mit Martinsturm","note":{"de":"Enge Gassen, alter Putz, kaum Verkehr – der ruhige Gegenpol zum Ufer.","tr":"Dar sokaklar, eski sıva, neredeyse trafik yok – kıyının sakin karşıtı."}}],"faq":[{"q":{"de":"Fahrt ihr für eine Hochzeit nach Österreich?","tr":"Bir düğün için Avusturya’ya gelir misiniz?"},"a":{"de":"Ja. Anfahrt, Übernachtung und die steuerlichen Punkte einer Auslandsleistung stehen dafür im Angebot, bevor etwas unterschrieben wird. Wir machen das nicht oft, aber wir machen es sauber.","tr":"Evet. Yol, konaklama ve yurt dışı hizmetin vergisel tarafı, hiçbir şey imzalanmadan önce teklifte yazıyor. Bunu sık yapmıyoruz ama düzgün yapıyoruz."}},{"q":{"de":"Lohnt sich der Pfänder am Hochzeitstag?","tr":"Düğün günü Pfänder’e çıkmak değer mi?"},"a":{"de":"Nur mit Zeitpuffer und guter Sicht. Wir rechnen mit rund anderthalb Stunden für Auffahrt, Bilder und Rückweg. Bei Hochnebel entscheiden wir am Morgen dagegen – ein Berg ohne Aussicht ist nur ein kalter Umweg.","tr":"Yalnızca zaman payı ve açık hava varsa. Çıkış, çekim ve dönüş için yaklaşık bir buçuk saat hesaplıyoruz. Alçak sis varsa sabah vazgeçiyoruz – manzarasız bir dağ yalnızca soğuk bir sapma olur."}}],"venues":[],"neighbours":["friedrichshafen","st-gallen","memmingen"]},{"slug":"st-gallen","name":"St. Gallen","kreis":{"de":"Kanton St. Gallen, Schweiz","tr":"St. Gallen kantonu, İsviçre"},"drive":{"de":"rund 2 Stunden 15","tr":"yaklaşık 2 saat 15"},"lead":{"de":"Hochzeitsfotograf und Videograf in St. Gallen – Stiftsbezirk, Erker und die weiteste Fahrt, die wir regelmäßig machen.","tr":"St. Gallen’de düğün fotoğrafçısı ve videografı – manastır bölgesi, cumbalar ve düzenli yaptığımız en uzun yol."},"body":{"de":["St. Gallen ist der äußerste Punkt unseres Gebiets, und wir nennen ihn trotzdem, weil die Fahrt sich für den Stiftsbezirk lohnt. Kathedrale und Stiftsbibliothek stehen auf der Welterbeliste, und der Platz davor hat eine Ruhe, die man in einer Stadt dieser Größe nicht erwartet. Fotografiert wird dort außen – die Bibliothek ist ein Buchmagazin, kein Ort für ein Brautkleid, und das respektieren wir.","Die Altstadt lebt von den Erkern: über hundert bemalte und geschnitzte Vorbauten an den Häusern, die schmalen Gassen Tiefe geben. Bei bedecktem Himmel ist das ideal, in praller Sonne wird es fleckig – hier ist ein grauer Tag ausnahmsweise die bessere Nachricht. Für Paare aus Deutschland gilt dasselbe wie für Bregenz: andere Währung, Zollformalitäten für Ausrüstung, eigene Rechnungsstellung. Wir haben das geregelt, aber es gehört vorher besprochen und nicht am Hochzeitsmorgen."],"tr":["St. Gallen bölgemizin en uç noktası ve yine de anıyoruz, çünkü yolculuk manastır bölgesi için değiyor. Katedral ve manastır kütüphanesi dünya mirası listesinde; önündeki meydanda bu büyüklükte bir şehirde beklenmeyecek bir sessizlik var. Çekim orada dışarıda oluyor – kütüphane bir kitap deposu, gelinlik için bir mekân değil ve buna saygı duyuyoruz.","Eski kent cumbalarla yaşıyor: evlerin üzerinde yüzden fazla boyalı ve oymalı çıkma, dar sokaklara derinlik veriyor. Kapalı havada bu ideal, tepedeki güneşte lekeli oluyor – burada gri bir gün istisnai olarak iyi haber. Almanya’dan gelen çiftler için Bregenz’le aynısı geçerli: başka para birimi, ekipman için gümrük işlemleri, ayrı faturalandırma. Bunu çözdük ama düğün sabahı değil, önceden konuşulması gerekiyor."]},"spots":[{"name":"Stiftsbezirk","note":{"de":"Kathedrale und Klosterhof, Welterbe. Außenaufnahmen; innen gelten strenge Regeln.","tr":"Katedral ve manastır avlusu, dünya mirası. Dış çekim; içeride katı kurallar var."}},{"name":"Altstadt mit den Erkern","note":{"de":"Über hundert bemalte Vorbauten. Bei bedecktem Himmel am besten, harte Sonne macht Flecken.","tr":"Yüzden fazla boyalı çıkma. En iyisi kapalı havada; sert güneş leke yapıyor."}},{"name":"Drei Weieren über der Stadt","note":{"de":"Weiher und Blick über St. Gallen, zwanzig Minuten vom Zentrum. Am Wochenende belebt.","tr":"Göletler ve şehre bakan manzara, merkezden yirmi dakika. Hafta sonu hareketli."}}],"faq":[{"q":{"de":"Kann man in der Stiftsbibliothek fotografieren?","tr":"Manastır kütüphanesinde fotoğraf çekilir mi?"},"a":{"de":"Nein, und das sollte man auch nicht wollen. Es ist ein Bibliotheksraum mit jahrhundertealten Beständen und entsprechendem Klima. Wir fotografieren im Klosterhof und am Platz davor – das gibt die Architektur genauso wieder.","tr":"Hayır ve istenmemeli de. Orası yüzyıllık koleksiyonları ve ona göre iklimi olan bir kütüphane salonu. Biz manastır avlusunda ve önündeki meydanda çekiyoruz – mimariyi o da aynı şekilde veriyor."}},{"q":{"de":"Rechnet ihr in Euro oder Franken ab?","tr":"Euro mu Frank mı üzerinden faturalıyorsunuz?"},"a":{"de":"In Euro, mit einem festen Betrag im Angebot – kein Kurs, der sich bis zur Hochzeit bewegt. Anfahrt und Übernachtung stehen getrennt daneben, damit ihr seht, wofür ihr zahlt.","tr":"Euro üzerinden ve teklifte sabit tutarla – düğüne kadar oynayan bir kur yok. Yol ve konaklama yanında ayrı yazıyor, neye ödediğinizi görün diye."}}],"venues":[],"neighbours":["bregenz","friedrichshafen","memmingen"]}],"venues":[{"faq":[{"a":{"de":"Ja, mehrfach. Wir kennen die Abläufe der Schlossverwaltung, die Wege für kurze Umbaupausen und die Stellen, an denen auch samstags keine Besuchergruppen im Bild stehen.","tr":"Evet, birçok kez. Saray idaresinin işleyişini, kısa aralarda kullanılan geçişleri ve cumartesileri bile ziyaretçi grubunun kadraja girmediği noktaları biliyoruz."},"q":{"de":"Habt ihr schon auf Schloss Solitude fotografiert?","tr":"Schloss Solitude\'da daha önce çekim yaptınız mı?"}},{"a":{"de":"40 Minuten reichen aus. Wenn ihr die Sichtachse und die Terrasse wollt, planen wir sie in die Stunde vor Sonnenuntergang.","tr":"40 dakika yeterli. Eksen ve terası istiyorsanız bunu gün batımından önceki saate planlıyoruz."},"q":{"de":"Wie viel Zeit braucht ihr für das Paarshooting am Schloss?","tr":"Sarayda çift çekimi için ne kadar süre gerekiyor?"}}],"body":{"de":["Schloss Solitude gehört zu den schönsten Trauorten der Region: die weiße Rokoko-Fassade, die lange Sichtachse Richtung Ludwigsburg und eine Terrasse, die abends im warmen Gegenlicht liegt. Für die Fotografie heißt das vor allem eines – hier entstehen große, ruhige Bilder, wenn man den richtigen Zeitpunkt trifft.","Weil das Schloss tagsüber öffentlich zugänglich ist, planen wir das Paarshooting bewusst in die Randzeiten. Zwischen 18:00 und 19:30 Uhr wird es merklich ruhiger, gleichzeitig steht die Sonne tief über der Sichtachse. Wir reservieren dafür rund 40 Minuten und sind rechtzeitig zurück, bevor der Empfang beginnt.","Für die Trauung selbst arbeiten wir ohne Blitz und mit lichtstarken Festbrennweiten. Die Fenster im Weißen Saal geben genug Licht für saubere, natürliche Aufnahmen – auch im Winter."],"tr":["Schloss Solitude bölgenin en güzel nikah mekânlarından biri: beyaz rokoko cephe, Ludwigsburg yönüne uzanan görüş ekseni ve akşamları sıcak kontra ışıkta kalan teras. Fotoğraf açısından bu şu demek – doğru saati tutturursanız burada büyük, sakin kareler çıkıyor.","Saray gündüz halka açık olduğu için çift çekimini bilerek sakin saatlere alıyoruz. 18:00–19:30 arası gözle görülür şekilde boşalıyor, aynı anda güneş de eksenin üzerinde alçalıyor. Buna yaklaşık 40 dakika ayırıyor ve karşılama başlamadan geri dönüyoruz.","Nikahta flaş kullanmıyor, geniş diyaframlı sabit lenslerle çalışıyoruz. Beyaz Salon\'un pencereleri kışın bile temiz ve doğal kareler için yeterli ışık veriyor."]},"city":"Stuttgart","lead":{"de":"Hochzeitsfotograf für Schloss Solitude in Stuttgart – wir kennen den Ablauf, das Licht auf der Terrasse und die ruhigen Ecken, wenn Tagesbesucher unterwegs sind.","tr":"Stuttgart Schloss Solitude için düğün fotoğrafçısı – akışı, terastaki ışığı ve ziyaretçi yoğunken sakin kalan köşeleri biliyoruz."},"name":"Schloss Solitude","slug":"schloss-solitude","type":{"de":"Schloss","tr":"Saray"},"light":{"de":"Beste Zeit für Portraits: 60–90 Minuten vor Sonnenuntergang auf der Südterrasse. Mittags hartes Licht – dann besser die Arkaden nutzen.","tr":"Portre için en iyi zaman: gün batımından 60–90 dakika önce güney terası. Öğle saatlerinde ışık sert – o zaman revakları kullanmak daha iyi."},"rules":{"de":["Fotogenehmigung für gewerbliche Shootings über die Schlossverwaltung","Kein Blitz und keine Stative im Innenbereich während der Trauung","Drohnenaufnahmen nicht gestattet – wir arbeiten mit Gimbal und Slider"],"tr":["Ticari çekimler için saray idaresinden izin gerekiyor","Nikah sırasında iç mekânda flaş ve tripod yok","Drone yasak – gimbal ve slider ile çalışıyoruz"]},"spots":{"de":["Sichtachse Richtung Ludwigsburg – lange Perspektive, ideal für Weitwinkel","Südterrasse mit Blick ins Tal – goldene Stunde","Arkadengang – Schattenlicht auch bei Mittagssonne","Kavaliersbauten – symmetrische Architekturbilder"],"tr":["Ludwigsburg yönündeki eksen – uzun perspektif, geniş açı için ideal","Vadiye bakan güney terası – altın saat","Revaklı geçit – öğle güneşinde bile gölge ışığı","Yan binalar – simetrik mimari kareler"]},"timing":[{"time":"14:00","what":{"de":"Getting Ready im Hotel, Anfahrt ca. 20 Min. aus der Innenstadt","tr":"Otelde hazırlık, merkezden yaklaşık 20 dk yol"}},{"time":"15:30","what":{"de":"Trauung im Weißen Saal – verfügbares Licht, kein Blitz","tr":"Beyaz Salon\'da nikah – mevcut ışık, flaşsız"}},{"time":"16:15","what":{"de":"Gratulation & Gruppenbilder vor der Hauptfassade","tr":"Tebrikler ve ana cephede grup fotoğrafları"}},{"time":"18:30","what":{"de":"Paarshooting Sichtachse & Terrasse (40 Min.)","tr":"Görüş ekseni ve terasta çift çekimi (40 dk)"}},{"time":"20:00","what":{"de":"Feier – Blitz mit Bounce, Bühnenbereich mit zweiter Kamera","tr":"Düğün – sektirmeli flaş, sahne için ikinci kamera"}}],"address":"Solitude 1, 70197 Stuttgart","capacity":{"de":"bis ca. 120 Gäste","tr":"yaklaşık 120 kişiye kadar"},"citySlug":"stuttgart","placeId":"","lat":"","lng":""},{"faq":[{"a":{"de":"Auf Wunsch ja. Wir übernehmen die Anmeldung und stimmen den Zeitraum so ab, dass er in euren Ablauf passt. Die Gebühr wird direkt mit dem Betreiber abgerechnet.","tr":"İsterseniz evet. Başvuruyu biz yapıyor, saati programınıza uyacak şekilde ayarlıyoruz. Ücret doğrudan işletmeye ödeniyor."},"q":{"de":"Kümmert ihr euch um die Fotogenehmigung im Blühenden Barock?","tr":"Blühendes Barock çekim iznini siz mi alıyorsunuz?"}},{"a":{"de":"Sehr. Die beleuchtete Fassade ergibt zwei bis drei Bilder, die man im Album später garantiert groß druckt – und es kostet euch nur zehn Minuten Feier.","tr":"Kesinlikle. Aydınlatılmış cephe, albümde büyük basacağınız iki üç kare veriyor – size sadece on dakikaya mal oluyor."},"q":{"de":"Lohnt sich ein Shooting zur blauen Stunde?","tr":"Mavi saat çekimi değer mi?"}}],"body":{"de":["Das Residenzschloss ist eine der größten barocken Schlossanlagen Deutschlands – und für die Fotografie ein Geschenk: symmetrische Innenhöfe, lange Fluchten, immer eine Wand im Schatten. Selbst an einem grellen Julitag findet man hier innerhalb von fünf Gehminuten weiches Licht.","Viele Paare kombinieren die Trauung im Schloss mit einem Shooting im Blühenden Barock. Das lohnt sich, braucht aber Planung: die Genehmigung muss vorab beantragt werden und der Weg vom Innenhof bis zu den Rosengärten dauert im Kleid gut zehn Minuten. Wir kalkulieren diesen Puffer von Anfang an mit ein.","Für den Abend gilt: die beleuchtete Fassade ergibt zur blauen Stunde – etwa 20 Minuten nach Sonnenuntergang – Bilder, die tagsüber nicht möglich sind. Zwei Minuten Unterbrechung der Feier reichen dafür völlig."],"tr":["Residenzschloss Almanya\'nın en büyük barok saray komplekslerinden biri – ve fotoğraf için tam bir hediye: simetrik iç avlular, uzun perspektifler, her saatte gölgede kalan bir duvar. Temmuzun en sert gününde bile beş dakika yürüyüşle yumuşak ışık bulunuyor.","Birçok çift saraydaki nikahı Blühendes Barock çekimiyle birleştiriyor. Buna değer ama planlama ister: izin önceden alınmalı ve iç avludan gül bahçelerine yürüyüş gelinlikle on dakikayı buluyor. Bu payı baştan hesaba katıyoruz.","Akşam için: aydınlatılmış cephe mavi saatte – gün batımından yaklaşık 20 dakika sonra – gündüz mümkün olmayan kareler veriyor. Bunun için düğüne iki dakika ara vermek yeterli."]},"city":"Ludwigsburg","lead":{"de":"Hochzeitsfotograf für das Residenzschloss Ludwigsburg – barocke Symmetrie, klare Bildsprache und ein Zeitplan, der zum Blühenden Barock passt.","tr":"Residenzschloss Ludwigsburg için düğün fotoğrafçısı – barok simetri, net görsel dil ve Blühendes Barock\'a uyan bir zaman planı."},"name":"Residenzschloss Ludwigsburg","slug":"residenzschloss-ludwigsburg","type":{"de":"Schloss","tr":"Saray"},"light":{"de":"Innenhöfe liefern ganztags weiches Schattenlicht. Blaue Stunde an der Hauptfassade: ca. 20 Minuten nach Sonnenuntergang.","tr":"İç avlular gün boyu yumuşak gölge ışığı veriyor. Ana cephede mavi saat: gün batımından ~20 dakika sonra."},"rules":{"de":["Gewerbliche Fotografie im Blühenden Barock ist genehmigungs- und kostenpflichtig","Im Museumsbereich ist Blitzlicht untersagt","Fahrzeuge nur über die ausgewiesenen Zufahrten – Anfahrt großzügig planen"],"tr":["Blühendes Barock\'ta ticari çekim izinli ve ücretli","Müze bölümünde flaş yasak","Araçlar yalnızca belirlenen girişlerden – yol için bol zaman bırakın"]},"spots":{"de":["Nördlicher Innenhof – symmetrisch, weiches Licht","Treppenhaus mit Handlauf – klassisches Kleid-Detail","Rosengarten im Blühenden Barock – nur mit Genehmigung","Hauptfassade zur blauen Stunde – beleuchtet"],"tr":["Kuzey iç avlu – simetrik, yumuşak ışık","Trabzanlı merdiven – klasik gelinlik detayı","Blühendes Barock gül bahçesi – sadece izinle","Mavi saatte aydınlatılmış ana cephe"]},"timing":[{"time":"11:00","what":{"de":"Getting Ready, Detailaufnahmen von Ringen, Kleid und Papeterie","tr":"Hazırlık; yüzük, gelinlik ve davetiye detayları"}},{"time":"13:00","what":{"de":"Trauung – verfügbares Licht, zweite Kamera für Reaktionen der Gäste","tr":"Nikah – mevcut ışık, misafir tepkileri için ikinci kamera"}},{"time":"14:00","what":{"de":"Sektempfang im Innenhof, lockere Reportage","tr":"İç avluda karşılama, serbest belgesel çekim"}},{"time":"15:30","what":{"de":"Shooting Blühendes Barock (Genehmigung erforderlich)","tr":"Blühendes Barock çekimi (izin gerekli)"}},{"time":"21:30","what":{"de":"Blaue Stunde an der Hauptfassade – 10 Minuten","tr":"Ana cephede mavi saat – 10 dakika"}}],"address":"Schlossstraße 30, 71634 Ludwigsburg","capacity":{"de":"je nach Saal 50–250 Gäste","tr":"salona göre 50–250 kişi"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Nicht, wenn richtig geleuchtet wird. Wir arbeiten mit zwei entfesselten Blitzen und Vollformatkameras, dadurch bleiben die Aufnahmen sauber und die Hauttöne natürlich.","tr":"Doğru ışıkla hayır. İki harici flaş ve full frame gövdelerle çalışıyoruz; kareler temiz, ten tonları doğal kalıyor."},"q":{"de":"Werden Bilder im dunklen Saal körnig?","tr":"Karanlık salonda kareler grenli çıkar mı?"}},{"a":{"de":"Ja. Ab 300 Gästen empfehlen wir zwei Fotografen und zwei Videografen, damit Bühne, Tische und Empfang gleichzeitig abgedeckt sind.","tr":"Evet. 300 kişiden itibaren iki fotoğrafçı ve iki videograf öneriyoruz; sahne, masalar ve karşılama aynı anda çekiliyor."},"q":{"de":"Kommt ihr auch für Hochzeiten mit 600 Gästen?","tr":"600 kişilik düğünlere de geliyor musunuz?"}}],"body":{"de":["Große Säle sind fotografisch anspruchsvoll: viel Mischlicht, farbige LED-Spots, dunkle Decken, an denen sich kein Blitz sauber bouncen lässt. Wer hier gute Bilder will, braucht ein Team, das mit entfesseltem Licht arbeitet – nicht nur mit dem Blitz auf der Kamera.","Wir bauen im SI-Centrum in der Regel zwei Blitzstative an den Saalrändern auf. Das ergibt saubere Trennung vom Hintergrund, natürliche Hauttöne und Bilder vom Einzug, die nicht flach wirken. Parallel filmt das Video-Team mit Gimbal – abgestimmt, damit sich Foto und Video nicht gegenseitig im Bild stehen.","Weil Hotel, Säle und Parkhaus im selben Komplex liegen, sind die Wege kurz. Das Getting Ready findet meist im Hotelzimmer statt: Fenster nach Süden, gute Größe, wir arbeiten dort ausschließlich mit Tageslicht."],"tr":["Büyük salonlar fotoğraf açısından zorlu: karışık ışık, renkli LED spotlar, flaşın sektirilemediği koyu tavanlar. Burada iyi kare isteyen çift, sadece kamera üstü flaşla değil harici ışıkla çalışan bir ekibe ihtiyaç duyar.","SI-Centrum\'da genelde salonun iki kenarına flaş ayağı kuruyoruz. Bu, arka plandan temiz ayrışma, doğal ten tonları ve düz görünmeyen giriş kareleri veriyor. Aynı anda video ekibi gimbal ile çekiyor – foto ve video birbirinin kadrajına girmeyecek şekilde koordineli.","Otel, salonlar ve otopark aynı kompleks içinde olduğu için mesafeler kısa. Hazırlık genelde otel odasında: güneye bakan pencere, geniş oda; orada sadece gün ışığıyla çalışıyoruz."]},"city":"Stuttgart","lead":{"de":"Hochzeitsfotograf & Videograf im SI-Centrum Stuttgart – erfahren mit großen Feiern, Bühnenprogramm und schwierigem Kunstlicht.","tr":"SI-Centrum Stuttgart\'ta düğün fotoğrafçısı ve videografı – büyük düğünler, sahne programı ve zor yapay ışıkta tecrübeli."},"name":"SI-Centrum Stuttgart","slug":"si-centrum-stuttgart","type":{"de":"Eventlocation & Hotel","tr":"Etkinlik mekânı & otel"},"light":{"de":"Sehr dunkler Saal, farbiges Kunstlicht. Wir arbeiten mit zwei entfesselten Blitzen plus lichtstarken Objektiven (f/1.4–1.8).","tr":"Çok karanlık salon, renkli yapay ışık. İki harici flaş ve geniş diyaframlı lenslerle (f/1.4–1.8) çalışıyoruz."},"rules":{"de":["Absprache mit der Haustechnik wegen Bühnenlicht und Nebelmaschine","Stative im Gästebereich nur am Rand","Zeitfenster für Dekoraufnahmen vor Einlass mit dem Veranstalter klären"],"tr":["Sahne ışığı ve sis makinesi için teknik ekiple görüşme","Misafir alanında tripodlar yalnızca kenarda","Süsleme çekimi için giriş öncesi zaman aralığını organizatörle netleştirin"]},"spots":{"de":["Hotelzimmer am Fenster – Getting Ready mit weichem Tageslicht","Foyer mit Glasfront – Empfangsbilder ohne Blitz","Bühne & Einzug – entfesseltes Blitzsetup","Außenbereich Richtung Filderpark für 20 Minuten Paarzeit"],"tr":["Otel odasında pencere kenarı – yumuşak gün ışığında hazırlık","Cam cepheli fuaye – flaşsız karşılama kareleri","Sahne ve giriş – harici flaş kurulumu","20 dakikalık çift çekimi için Filderpark yönündeki dış alan"]},"timing":[{"time":"13:00","what":{"de":"Getting Ready im Hotelzimmer – Tageslicht am Fenster","tr":"Otel odasında hazırlık – pencerede gün ışığı"}},{"time":"16:00","what":{"de":"First Look & Paarshooting draußen, bevor die Gäste eintreffen","tr":"İlk görüşme ve dışarıda çift çekimi, misafirler gelmeden"}},{"time":"18:00","what":{"de":"Empfang, Saaldekor und Details vor dem Einzug","tr":"Karşılama, salon süslemesi ve giriş öncesi detaylar"}},{"time":"19:00","what":{"de":"Einzug mit Bühnenlicht – zwei Fotografen, zwei Perspektiven","tr":"Sahne ışığında giriş – iki fotoğrafçı, iki açı"}},{"time":"22:00","what":{"de":"Party, Konfetti, offene Reportage bis Ende","tr":"Parti, konfeti, sona kadar serbest çekim"}}],"address":"Plieninger Straße 100, 70567 Stuttgart","capacity":{"de":"bis ca. 800 Gäste","tr":"yaklaşık 800 kişiye kadar"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Der Aufstieg dauert etwa fünf Minuten. Wir planen 30 Minuten insgesamt ein – die Gäste merken kaum, dass ihr weg wart.","tr":"Çıkış yaklaşık beş dakika. Toplam 30 dakika planlıyoruz – misafirler ayrıldığınızı neredeyse fark etmiyor."},"q":{"de":"Wie kommen wir in die Weinberge, ohne die Feier lange zu verlassen?","tr":"Düğünden uzun süre ayrılmadan bağlara nasıl çıkarız?"}}],"body":{"de":["Die Alte Kelter ist eine der beliebtesten Hochzeitslocations im Rems-Murr-Kreis: massive Holzbalken, hohe Decken und ein Raumgefühl, das auch bei 400 Gästen nicht kalt wirkt. Fotografisch ist das Holz ein Vorteil – Blitzlicht bekommt hier eine warme, angenehme Färbung, statt wie in weißen Sälen flach zu wirken.","Der größte Trumpf liegt aber draußen: die Rebhänge am Kappelberg sind in fünf Minuten zu Fuß erreichbar. Wer die goldene Stunde nutzt, bekommt Portraits, die aussehen wie aus der Toskana – ohne die Feier länger als eine halbe Stunde zu verlassen.","Für den Ablauf empfehlen wir, den Einzug nicht zu spät zu legen. Wenn das Tageslicht durch die Hallenfenster noch mitspielt, entstehen deutlich lebendigere Bilder als bei reinem Kunstlicht."],"tr":["Alte Kelter, Rems-Murr bölgesinin en sevilen düğün mekânlarından biri: kalın ahşap kirişler, yüksek tavan ve 400 kişide bile soğuk durmayan bir atmosfer. Fotoğraf açısından ahşap avantaj – flaş ışığı beyaz salonlardaki gibi düz kalmıyor, sıcak bir renk alıyor.","Ama asıl kozu dışarıda: Kappelberg bağları beş dakika yürüme mesafesinde. Altın saati kullanan çift, düğünden yarım saatten fazla ayrılmadan Toskana havasında portreler alıyor.","Akış için önerimiz: girişi çok geç saate koymayın. Salon pencerelerinden gün ışığı hâlâ giriyorsa, sadece yapay ışığa göre çok daha canlı kareler çıkıyor."]},"city":"Fellbach","lead":{"de":"Hochzeitsfotograf für die Alte Kelter in Fellbach – warmes Holz, große Feiern und Weinberge fünf Minuten entfernt.","tr":"Fellbach Alte Kelter için düğün fotoğrafçısı – sıcak ahşap, büyük düğünler ve beş dakika ötede bağlar."},"name":"Alte Kelter Fellbach","slug":"alte-kelter-fellbach","type":{"de":"Festhalle / Kelter","tr":"Düğün salonu / şaraphane"},"light":{"de":"Warmes Holz reflektiert Blitzlicht angenehm. Tageslicht durch die Seitenfenster bis ca. eine Stunde vor Sonnenuntergang nutzbar.","tr":"Sıcak ahşap flaş ışığını hoş yansıtıyor. Yan pencerelerden gelen gün ışığı, gün batımından ~1 saat öncesine kadar kullanılabilir."},"rules":{"de":["Dekoaufnahmen nur im Zeitfenster vor dem Gästeeinlass möglich","Rauchmaschinen mit dem Hallenbetrieb abstimmen","Nachtaufnahmen draußen benötigen ein zusätzliches Dauerlicht – bringen wir mit"],"tr":["Süsleme çekimi yalnızca misafir girişinden önceki aralıkta mümkün","Sis makinesi için salon yönetimiyle görüşün","Dışarıda gece çekimi ek sürekli ışık gerektirir – biz getiriyoruz"]},"spots":{"de":["Rebhänge Kappelberg – goldene Stunde, 5 Gehminuten","Holzbalkenhalle im Gegenlicht der Seitenfenster","Innenhof / Vorplatz für Gruppenbilder","Weinberg-Treppen für Aufnahmen von oben"],"tr":["Kappelberg bağları – altın saat, 5 dakika yürüyüş","Yan pencerelerin kontra ışığında ahşap kirişli salon","Grup fotoğrafları için iç avlu / meydan","Yukarıdan çekimler için bağ merdivenleri"]},"timing":[{"time":"15:00","what":{"de":"Dekoaufnahmen im leeren Saal – vor dem Einlass","tr":"Boş salonda süsleme çekimi – misafir girişinden önce"}},{"time":"17:00","what":{"de":"Empfang draußen, Reportage der Begrüßung","tr":"Dışarıda karşılama, belgesel çekim"}},{"time":"19:30","what":{"de":"Paarshooting Rebhänge Kappelberg (30 Min.)","tr":"Kappelberg bağlarında çift çekimi (30 dk)"}},{"time":"20:30","what":{"de":"Einzug, Tanz, Programm mit entfesseltem Licht","tr":"Giriş, dans, harici ışıkla program"}}],"address":"Kelterweg 1, 70734 Fellbach","capacity":{"de":"bis ca. 500 Gäste","tr":"yaklaşık 500 kişiye kadar"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Ja. Innenhof und Arkaden bieten genügend geschützte Flächen, in denen wir auch bei Regen saubere Portraits machen können.","tr":"Evet. İç avlu ve revaklar, yağmurda da temiz portre çekebileceğimiz yeterli korunaklı alan sunuyor."},"q":{"de":"Ist Schloss Hohenheim auch bei Regen eine gute Wahl?","tr":"Yağmurlu havada Schloss Hohenheim iyi bir tercih mi?"}}],"body":{"de":["Schloss Hohenheim ist die ruhige Alternative zu den großen Schlossanlagen. Die helle Fassade wirft weiches Reflexlicht auf das Brautpaar, der Park liefert Schatten, wenn die Sonne zu hart steht, und der Exotische Garten gibt Bilder, die man nicht sofort einer Region zuordnet.","Weil das Gelände zur Universität gehört, ist es an Wochenenden angenehm leer. Für Hochzeiten mit kleiner Gästezahl ist das ideal: keine Wartezeiten, keine Zuschauer, kurze Wege zwischen Trauort, Empfang und Portraits."],"tr":["Schloss Hohenheim, büyük saray komplekslerinin sakin alternatifi. Aydınlık cephe çifte yumuşak yansıma ışığı veriyor, park güneş sertleştiğinde gölge sunuyor ve Egzotik Bahçe, hangi bölgeye ait olduğu hemen anlaşılmayan kareler çıkarıyor.","Alan üniversiteye ait olduğu için hafta sonları oldukça boş. Küçük davetli sayılı düğünler için ideal: bekleme yok, izleyici yok, nikah–karşılama–portre arası mesafeler kısa."]},"city":"Stuttgart-Hohenheim","lead":{"de":"Hochzeitsfotograf für Schloss Hohenheim – heller Klassizismus, ein weitläufiger Park und viel Grün für Portraits.","tr":"Schloss Hohenheim için düğün fotoğrafçısı – aydınlık neoklasik mimari, geniş bir park ve portreler için bol yeşil."},"name":"Schloss Hohenheim","slug":"schloss-hohenheim","type":{"de":"Schloss","tr":"Saray"},"light":{"de":"Helle Fassade als natürlicher Reflektor. Park mit gleichmäßigem Schattenlicht auch mittags.","tr":"Aydınlık cephe doğal reflektör görevi görüyor. Park öğlen bile dengeli gölge ışığı veriyor."},"rules":{"de":["Universitätsgelände – Termine am Wochenende sind deutlich ruhiger","Gewerbliche Aufnahmen im Park vorab anmelden"],"tr":["Üniversite alanı – hafta sonu randevuları çok daha sakin","Parkta ticari çekim için önceden bildirim gerekli"]},"spots":{"de":["Hauptfassade – heller Reflektor, ideal für Gruppenbilder","Exotischer Garten – ungewöhnliches Grün","Landesarboretum – alte Baumbestände, weiches Licht","Innenhof – geschützt bei Regen"],"tr":["Ana cephe – aydınlık reflektör, grup fotoğrafı için ideal","Egzotik Bahçe – alışılmadık bir yeşil","Arboretum – yaşlı ağaçlar, yumuşak ışık","İç avlu – yağmurda korunaklı"]},"timing":[{"time":"12:00","what":{"de":"Trauung – ruhiger Rahmen, verfügbares Licht","tr":"Nikah – sakin ortam, mevcut ışık"}},{"time":"13:00","what":{"de":"Gratulation und Gruppenbilder vor der Fassade","tr":"Tebrikler ve cephe önünde grup fotoğrafları"}},{"time":"14:30","what":{"de":"Portraits im Park und im Exotischen Garten","tr":"Parkta ve Egzotik Bahçe\'de portreler"}},{"time":"17:00","what":{"de":"Feier – Reportage bis zum ersten Tanz","tr":"Düğün – ilk dansa kadar belgesel çekim"}}],"address":"Schloss Hohenheim, 70599 Stuttgart","capacity":{"de":"bis ca. 150 Gäste","tr":"yaklaşık 150 kişiye kadar"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Ja, wenn die Location stimmt. Wir arbeiten mit klaren Ansagen statt endlosem Posieren – 30 Minuten ergeben in der Regel 40 bis 60 fertige Bilder.","tr":"Mekân doğruysa evet. Bitmeyen poz yerine net yönlendirmelerle çalışıyoruz – 30 dakika genelde 40–60 bitmiş kare veriyor."},"q":{"de":"Reichen 30 Minuten für ein Paarshooting wirklich?","tr":"Çift çekimi için 30 dakika gerçekten yeter mi?"}}],"body":{"de":["Der Park an der Villa Berg ist unser Favorit für kurze Shootings mitten in Stuttgart. Wer im Rathaus heiratet, ist in zehn Minuten hier – und steht plötzlich zwischen alten Bäumen statt in der Innenstadt.","Für Paare mit engem Zeitplan bedeutet das: 30 Minuten reichen für eine komplette Portraitserie. Kein Umziehen, kein langes Fahren, keine Parkplatzsuche."],"tr":["Villa Berg parkı, Stuttgart\'ın göbeğinde kısa çekimler için favorimiz. Belediyede nikah kıyan çift on dakikada burada – ve birden şehir merkezi yerine yaşlı ağaçların arasında.","Programı sıkışık çiftler için bu şu demek: 30 dakika tam bir portre serisine yetiyor. Kıyafet değişimi yok, uzun yol yok, park yeri derdi yok."]},"city":"Stuttgart-Ost","lead":{"de":"Hochzeitsfotograf rund um die Villa Berg in Stuttgart-Ost – urbaner Park, ruhige Wege, ideal für Paarshootings zwischen Standesamt und Feier.","tr":"Stuttgart-Ost\'ta Villa Berg çevresinde düğün fotoğrafçısı – şehir içinde park, sakin yollar; nikah ile düğün arasındaki çift çekimi için ideal."},"name":"Villa Berg & Umgebung","slug":"villa-berg","type":{"de":"Villa / Park","tr":"Villa / park"},"light":{"de":"Alter Baumbestand streut das Licht. Auch mittags nutzbar – im Gegensatz zu offenen Plätzen in der Innenstadt.","tr":"Yaşlı ağaçlar ışığı yayıyor. Şehir merkezindeki açık meydanların aksine öğlen de kullanılabilir."},"rules":{"de":["Öffentlicher Park – bitte Rücksicht auf Besucher nehmen","Kein Aufbau von großen Lichtstativen auf den Hauptwegen"],"tr":["Halka açık park – ziyaretçilere dikkat","Ana yollarda büyük ışık ayakları kurulmuyor"]},"spots":{"de":["Alleen im Park – lange Fluchten","Treppenanlagen – Höhe und Struktur im Bild","Wiesenflächen – weiches Gegenlicht am Nachmittag"],"tr":["Park içindeki ağaçlı yollar – uzun perspektif","Merdivenler – kadrajda kot farkı ve doku","Çayırlar – öğleden sonra yumuşak kontra ışık"]},"timing":[{"time":"10:30","what":{"de":"Trauung im Standesamt Stuttgart","tr":"Stuttgart nikah dairesinde tören"}},{"time":"11:30","what":{"de":"Fahrt zum Park (10 Min.)","tr":"Parka geçiş (10 dk)"}},{"time":"11:45","what":{"de":"Paarshooting im Park – 30 Minuten","tr":"Parkta çift çekimi – 30 dakika"}},{"time":"13:00","what":{"de":"Weiterfahrt zur Feier","tr":"Düğün mekânına hareket"}}],"address":"Villa Berg, 70190 Stuttgart","capacity":{"de":"kleine bis mittlere Feiern","tr":"küçük ve orta ölçekli kutlamalar"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Immer vor dem Gästeeinlass. Sobald die Halle voll ist, sind saubere Übersichtsbilder der Dekoration praktisch nicht mehr möglich.","tr":"Her zaman misafirler girmeden önce. Salon dolduktan sonra süslemenin temiz genel karesi pratikte mümkün olmuyor."},"q":{"de":"Wann sollten die Dekoaufnahmen entstehen?","tr":"Süsleme çekimleri ne zaman yapılmalı?"}}],"body":{"de":["Die Filderhalle ist eine der meistgebuchten Hallen im Süden Stuttgarts – gute Autobahnanbindung, Parkplätze direkt am Haus und ein Saal, der sich flexibel bestuhlen lässt. Fotografisch ist sie ein klassischer Fall: neutraler Raum, viel Kunstlicht, das Bild entsteht durch Menschen und Licht, nicht durch die Architektur.","Deshalb legen wir hier besonderen Wert auf die Dekoaufnahmen vor dem Einlass und auf ein sauberes Blitzsetup für Einzug und Bühne. Für Portraits fahren wir mit dem Paar zehn Minuten Richtung Felder – dort entsteht der Kontrast zur Halle."],"tr":["Filderhalle, Stuttgart\'ın güneyinde en çok tercih edilen salonlardan biri – otoyola yakın, kapıda otopark ve esnek oturma düzeni. Fotoğraf açısından klasik bir durum: nötr mekân, bol yapay ışık; kareyi mimari değil insanlar ve ışık kuruyor.","Bu yüzden burada giriş öncesi süsleme çekimine ve giriş/sahne için temiz bir flaş kurulumuna özellikle önem veriyoruz. Portreler için çiftle on dakika tarlalara doğru çıkıyoruz – salona kontrast orada oluşuyor."]},"city":"Leinfelden-Echterdingen","lead":{"de":"Hochzeitsfotograf & Videograf für die Filderhalle in Leinfelden-Echterdingen – große Feiern, klare Reportage, planbarer Ablauf.","tr":"Leinfelden-Echterdingen Filderhalle için düğün fotoğrafçısı ve videografı – büyük düğünler, net belgesel çekim, planlanabilir akış."},"name":"Filderhalle Leinfelden","slug":"filderhalle-leinfelden","type":{"de":"Festhalle / Eventlocation","tr":"Düğün salonu / etkinlik mekânı"},"light":{"de":"Neutrales Hallenlicht. Wir setzen zwei entfesselte Blitze und nutzen Tageslicht durch das Foyer, solange es geht.","tr":"Nötr salon ışığı. İki harici flaş kuruyor, mümkün olduğunca fuayedeki gün ışığını kullanıyoruz."},"rules":{"de":["Zeitfenster für Dekoaufnahmen mit dem Veranstalter fest einplanen","Technik-Absprache wegen Bühnenlicht empfohlen"],"tr":["Süsleme çekimi için organizatörle net bir saat belirleyin","Sahne ışığı için teknik ekiple görüşülmesi önerilir"]},"spots":{"de":["Foyer mit Glasfront – natürliches Licht für Empfangsbilder","Felder und Alleen Richtung Echterdingen – 10 Minuten Fahrt","Haupteingang bei Nacht – Dauerlicht für Gruppenaufnahmen"],"tr":["Cam cepheli fuaye – karşılama kareleri için doğal ışık","Echterdingen yönündeki tarlalar ve ağaçlı yollar – 10 dakika","Gece ana giriş – grup çekimleri için sürekli ışık"]},"timing":[{"time":"16:00","what":{"de":"Saal- und Dekoaufnahmen vor dem Einlass","tr":"Giriş öncesi salon ve süsleme çekimi"}},{"time":"17:30","what":{"de":"Empfang im Foyer – Tageslicht","tr":"Fuayede karşılama – gün ışığı"}},{"time":"19:00","what":{"de":"Paarshooting draußen, 20 Minuten","tr":"Dışarıda çift çekimi, 20 dakika"}},{"time":"20:00","what":{"de":"Einzug & Programm mit Blitzsetup","tr":"Giriş ve program, flaş kurulumuyla"}}],"address":"Bahnhofstraße 61, 70771 Leinfelden-Echterdingen","capacity":{"de":"bis ca. 600 Gäste","tr":"yaklaşık 600 kişiye kadar"},"citySlug":"stuttgart"}],"contact":{"zip":"86381","city":"Krumbach (Schwaben)","email":"hallo@atelier-lumiere.de","hours":{"de":"Mo–Fr 10:00–18:00 · Sa nach Vereinbarung","tr":"Pzt–Cu 10:00–18:00 · Cmt randevuyla"},"phone":"","street":"","instagram":"https://instagram.com/","mapsQuery":"","phoneHuman":""},"process":[{"step":"01","text":{"de":"Ein Gespräch per Video oder im Atelier. Ihr erzählt vom Tag, wir sagen ehrlich, was zeitlich realistisch ist.","tr":"Video ile ya da atölyede bir görüşme. Siz günü anlatıyorsunuz, biz zaman açısından neyin gerçekçi olduğunu açıkça söylüyoruz."},"title":{"de":"Kennenlernen","tr":"Tanışma"}},{"step":"02","text":{"de":"Vier Wochen vorher erstellen wir gemeinsam einen Ablaufplan – inklusive Lichtzeiten und Puffer für die Location.","tr":"Dört hafta önce birlikte bir akış planı çıkarıyoruz – ışık saatleri ve mekân için zaman payı dahil."},"title":{"de":"Zeitplan","tr":"Zaman planı"}},{"step":"03","text":{"de":"Wir sind da, bevor es losgeht, und bleiben, bis die Party läuft. Ohne Kommandos, ohne Unterbrechung.","tr":"Başlamadan önce oradayız ve parti oturana kadar kalıyoruz. Komut yok, kesinti yok."},"title":{"de":"Der Tag","tr":"Düğün günü"}},{"step":"04","text":{"de":"Nach drei Wochen bekommt ihr eure private Galerie. Dort markiert ihr per Herz die Bilder fürs Album – wir sehen die Auswahl direkt.","tr":"Üç hafta sonra özel galeriniz hazır. Albüm için kareleri kalp ile işaretliyorsunuz – seçiminizi anında görüyoruz."},"title":{"de":"Galerie & Auswahl","tr":"Galeri & seçim"}}],"stories":[{"body":{"de":["Elif und Marco wollten zwei Traditionen in einen Tag bringen, ohne dass sich eine davon wie ein Programmpunkt anfühlt. Der Morgen gehörte der Familie, der Nachmittag der Trauung im Weißen Saal, der Abend dem Fest.","Für uns war das ein Tag mit vielen kleinen Übergängen – und genau die machen so eine Reportage aus. Das schönste Bild entstand nicht beim Shooting, sondern als Elifs Großmutter ihr kurz vor dem Einzug die Hand hielt."],"tr":["Elif ve Marco iki geleneği tek güne sığdırmak istiyordu, ama hiçbiri program maddesi gibi durmasın diye. Sabah aileye, öğleden sonra Beyaz Salon\'daki nikaha, akşam da düğüne ayrıldı.","Bizim için bu, çok sayıda küçük geçişin olduğu bir gündü – ve böyle bir çekimi asıl bunlar oluşturur. En güzel kare çekim sırasında değil, girişten hemen önce Elif\'in babaannesi elini tuttuğunda çıktı."]},"slug":"elif-marco-schloss-solitude","intro":{"de":"Eine deutsch-türkische Hochzeit auf Schloss Solitude – mit Sonnenuntergang auf der Sichtachse und Feier bis halb zwei.","tr":"Schloss Solitude\'da Türk-Alman düğünü – eksende gün batımı ve gece bir buçuğa kadar kutlama."},"month":{"de":"Juni","tr":"Haziran"},"quote":{"de":"Wir haben euch den ganzen Tag kaum gesehen – und trotzdem ist alles auf den Bildern.","tr":"Sizi gün boyu neredeyse hiç görmedik – ama her şey karelerde var."},"seeds":["story-elif-1","story-elif-2","story-elif-3","story-elif-4","story-elif-5","story-elif-6"],"venue":{"de":"Schloss Solitude, Stuttgart","tr":"Schloss Solitude, Stuttgart"},"couple":"Elif & Marco","guests":"120","citySlug":"stuttgart","venueSlug":"schloss-solitude","uploads":[]},{"body":{"de":["Bei 260 Gästen bleibt selten Zeit für Portraits. Wir haben deshalb im Vorgespräch ein festes Fenster vereinbart: 19:30 Uhr, 30 Minuten, Rebhänge. Der Rest des Abends gehörte der Reportage.","Die Bilder aus dieser halben Stunde sind die, die heute im Wohnzimmer hängen – und trotzdem hat niemand gemerkt, dass das Brautpaar kurz weg war."],"tr":["260 kişide portreye nadiren zaman kalır. Bu yüzden ön görüşmede sabit bir aralık belirledik: 19:30, 30 dakika, bağlar. Akşamın kalanı belgesel çekime kaldı.","Bugün oturma odasında asılı olan kareler o yarım saatten – yine de kimse çiftin kısa süre ayrıldığını fark etmedi."]},"slug":"sarah-daniel-alte-kelter","intro":{"de":"Weinberge, warmes Holz und eine Feier, die um 19:30 Uhr für 30 Minuten in den Kappelberg ausgewichen ist.","tr":"Bağlar, sıcak ahşap ve 19:30\'da otuz dakikalığına Kappelberg\'e çıkan bir düğün."},"month":{"de":"September","tr":"Eylül"},"quote":{"de":"Die halbe Stunde in den Weinbergen war die beste Entscheidung des Tages.","tr":"Bağlardaki o yarım saat günün en iyi kararıydı."},"seeds":["story-sarah-1","story-sarah-2","story-sarah-3","story-sarah-4","story-sarah-5","story-sarah-6"],"venue":{"de":"Alte Kelter, Fellbach","tr":"Alte Kelter, Fellbach"},"couple":"Sarah & Daniel","guests":"260","citySlug":"stuttgart","venueSlug":"alte-kelter-fellbach"},{"body":{"de":["Große Hallen sind eine Lichtfrage. Wir haben zwei Blitzstative gesetzt, das Video-Team hat mit Gimbal gearbeitet, und der Einzug wurde aus zwei Perspektiven gleichzeitig aufgenommen.","Für das Paarshooting sind wir um 16:00 Uhr raus, bevor die Gäste kamen – 25 Minuten, die den Unterschied gemacht haben."],"tr":["Büyük salonlar bir ışık meselesidir. İki flaş ayağı kurduk, video ekibi gimbal ile çalıştı ve giriş aynı anda iki açıdan kaydedildi.","Çift çekimi için misafirler gelmeden 16:00\'da dışarı çıktık – farkı yaratan 25 dakika."]},"slug":"aylin-emre-si-centrum","intro":{"de":"600 Gäste, Bühnenprogramm, Konfetti – eine große Feier, die trotzdem ruhige Bilder zulässt.","tr":"600 kişi, sahne programı, konfeti – buna rağmen sakin kareler veren büyük bir düğün."},"month":{"de":"August","tr":"Ağustos"},"quote":{"de":"Wir hatten Angst, dass die Bilder im dunklen Saal nichts werden. Das Gegenteil ist passiert.","tr":"Karanlık salonda kareler olmaz diye korkuyorduk. Tam tersi oldu."},"seeds":["story-aylin-1","story-aylin-2","story-aylin-3","story-aylin-4","story-aylin-5","story-aylin-6"],"venue":{"de":"SI-Centrum, Stuttgart","tr":"SI-Centrum, Stuttgart"},"couple":"Aylin & Emre","guests":"600","citySlug":"stuttgart","venueSlug":"si-centrum-stuttgart"},{"body":{"de":["Lena und Jonas hatten eine klare Vorstellung: wenig Inszenierung, viel Familie. Wir haben den Tag entsprechend leicht gehalten und nur zwei feste Blöcke gesetzt – das Shooting im Park und die blaue Stunde.","Die Genehmigung für das Blühende Barock haben wir vier Wochen vorher beantragt. Das ist der Punkt, an dem Erfahrung Zeit spart."],"tr":["Lena ve Jonas\'ın net bir isteği vardı: az kurgu, çok aile. Günü buna göre hafif tuttuk ve sadece iki sabit blok koyduk – parktaki çekim ve mavi saat.","Blühendes Barock iznini dört hafta önceden aldık. Tecrübenin zaman kazandırdığı nokta tam burası."]},"slug":"lena-jonas-residenzschloss","intro":{"de":"Barocke Innenhöfe, ein Shooting im Blühenden Barock und zehn Minuten blaue Stunde an der Fassade.","tr":"Barok iç avlular, Blühendes Barock\'ta çekim ve cephede on dakikalık mavi saat."},"month":{"de":"Mai","tr":"Mayıs"},"quote":{"de":"Ihr habt den Zeitplan gerettet, bevor wir überhaupt gemerkt haben, dass es einen gibt.","tr":"Bir program olduğunu biz fark etmeden siz o programı kurtardınız."},"seeds":["story-lena-1","story-lena-2","story-lena-3","story-lena-4","story-lena-5","story-lena-6"],"venue":{"de":"Residenzschloss, Ludwigsburg","tr":"Residenzschloss, Ludwigsburg"},"couple":"Lena & Jonas","guests":"90","citySlug":"stuttgart","venueSlug":"residenzschloss-ludwigsburg"}],"campaign":{"code":"lumiere2026","active":true},"packages":[{"hint":{"de":"4 Stunden Begleitung","tr":"4 saat çekim"},"name":{"de":"Standesamt & Feier","tr":"Nikah & Kutlama"},"slug":"standesamt","price":"690 €","features":{"de":["4 Stunden Fotoreportage","ca. 150 bearbeitete Bilder","Private Online-Galerie, 12 Monate online","Download in voller Auflösung","Lieferung in 10 Werktagen"],"tr":["4 saat fotoğraf çekimi","yaklaşık 150 düzenlenmiş kare","Özel online galeri, 12 ay erişim","Tam çözünürlük indirme","10 iş gününde teslim"]},"featured":false},{"hint":{"de":"10 Stunden, Getting Ready bis Party","tr":"10 saat, hazırlıktan partiye"},"name":{"de":"Der ganze Tag","tr":"Tüm Gün"},"slug":"klassik","price":"1.890 €","featured":true,"features":{"de":["10 Stunden Fotoreportage","Zweiter Fotograf ab 150 Gästen","400–600 bearbeitete Bilder","Paarshooting zur goldenen Stunde","Private Online-Galerie mit Foto-Auswahl fürs Album","Digitale Hochzeitseinladung gratis","Lieferung in 3 Wochen"],"tr":["10 saat fotoğraf çekimi","150 kişiden itibaren ikinci fotoğrafçı","400–600 düzenlenmiş kare","Altın saatte çift çekimi","Albüm seçimi yapılabilen özel online galeri","Dijital düğün davetiyesi ücretsiz","3 haftada teslim"]}},{"hint":{"de":"Team aus 2 Personen, ganzer Tag","tr":"2 kişilik ekip, tüm gün"},"name":{"de":"Foto & Film","tr":"Foto & Film"},"slug":"foto-video","price":"3.490 €","features":{"de":["Alles aus „Der ganze Tag“","Highlight-Film 4–6 Minuten in 4K","Funkmikrofone für Trauung & Reden","Vertikale Social-Version","Ungeschnittener Mitschnitt der Trauung","Digitale Hochzeitseinladung gratis","Lieferung Film in 6 Wochen"],"tr":["„Tüm Gün“ paketindeki her şey","4K\'da 4–6 dakikalık highlight film","Nikah ve konuşmalar için telsiz mikrofon","Sosyal medya için dikey versiyon","Nikahın kesilmemiş kaydı","Dijital düğün davetiyesi ücretsiz","Film teslimi 6 hafta"]},"featured":false}],"services":[{"body":{"de":["Unsere Reportagen leben von echten Momenten: der Blick der Mutter beim Ankleiden, die zitternden Hände beim Ringtausch, der Vater, der sich beim ersten Tanz wegdreht. Dafür arbeiten wir leise, mit zwei Kameras und ohne den Tag zu unterbrechen.","Ein Paarshooting von 30 bis 45 Minuten planen wir trotzdem ein – nicht für gestellte Posen, sondern für die zwei, drei ruhigen Bilder, die später über dem Sofa hängen."],"tr":["Çekimlerimiz gerçek anlardan besleniyor: gelin hazırlanırken annenin bakışı, yüzük takılırken titreyen eller, ilk dansta başını çeviren baba. Bunun için sessiz çalışıyor, iki gövde kullanıyor ve günü bölmüyoruz.","Yine de 30–45 dakikalık bir çift çekimi planlıyoruz – kurgulu pozlar için değil, sonradan duvara asılacak o iki üç sakin kare için."]},"seed":"lum-service-foto","slug":"hochzeitsfotografie","short":{"de":"Dokumentarisch, ruhig, ohne stundenlanges Posieren. Wir halten fest, was ohnehin passiert.","tr":"Belgesel tarzda, sakin, saatlerce poz vermeden. Zaten yaşananı kayda alıyoruz."},"title":{"de":"Hochzeitsfotografie","tr":"Düğün Fotoğrafçılığı"},"bullets":{"de":["Zwei Fotografen bei Feiern ab 150 Gästen","Vollformat-Technik, lichtstarke Festbrennweiten","Farb- und Schwarzweiß-Bearbeitung von Hand","Online-Galerie mit Download in voller Auflösung"],"tr":["150 kişiden büyük düğünlerde iki fotoğrafçı","Full frame ekipman, geniş diyaframlı sabit lensler","Elde renk ve siyah-beyaz düzenleme","Tam çözünürlük indirmeli online galeri"]}},{"body":{"de":["Der Highlight-Film dauert vier bis sechs Minuten. Er ist so geschnitten, dass er auch Gäste mitnimmt, die nicht dabei waren: die Rede des Vaters als Tonspur, der Einzug in Zeitlupe, das Lachen beim Anschneiden der Torte.","Auf Wunsch gibt es zusätzlich den ungeschnittenen Mitschnitt von Trauung und Reden – für die Familie oft das Wichtigste."],"tr":["Highlight film dört ila altı dakika. Orada olmayan misafirleri de içine alacak şekilde kurgulanıyor: ses olarak babanın konuşması, ağır çekimde giriş, pasta kesiminde kahkaha.","İsteğe bağlı olarak nikah ve konuşmaların kesilmemiş kaydı da veriliyor – aile için çoğu zaman en değerlisi bu."]},"seed":"lum-service-video","slug":"hochzeitsvideo","short":{"de":"Ein Film, den ihr wirklich anschaut – kurz, musikalisch, mit euren Stimmen.","tr":"Gerçekten izleyeceğiniz bir film – kısa, müzikli, kendi seslerinizle."},"title":{"de":"Hochzeitsfilm & Video","tr":"Düğün Filmi & Video"},"bullets":{"de":["Highlight-Film 4–6 Minuten in 4K","Funkmikrofone für Reden und Zeremonie","Gimbal & Slider, keine hektischen Schnitte","Vertikale Version für Instagram inklusive"],"tr":["4K\'da 4–6 dakikalık highlight film","Konuşma ve tören için telsiz mikrofon","Gimbal ve slider, telaşlı kurgu yok","Instagram için dikey versiyon dahil"]}},{"body":{"de":["Nicht jede Hochzeit dauert zwölf Stunden. Für standesamtliche Trauungen, Verlobungen und Henna-Abende gibt es kompakte Pakete ab zwei Stunden – mit derselben Technik und derselben Bildsprache wie bei den großen Feiern."],"tr":["Her düğün on iki saat sürmüyor. Resmi nikah, nişan ve kına geceleri için iki saatten başlayan kompakt paketler var – büyük düğünlerdeki aynı ekipman ve aynı görsel dille."]},"seed":"lum-service-standesamt","slug":"standesamt","short":{"de":"Kompakte Begleitung für kleine Feiern, Verlobungen und Henna-Abende.","tr":"Küçük kutlamalar, nişan ve kına geceleri için kompakt çekim."},"title":{"de":"Standesamt & Verlobung","tr":"Nikah & Nişan"},"bullets":{"de":["Ab 2 Stunden buchbar","Ideal für Henna-Abend & Verlobung","Lieferung innerhalb von 10 Tagen","Aufstockung auf Tagespaket jederzeit möglich"],"tr":["2 saatten itibaren","Kına gecesi ve nişan için ideal","10 gün içinde teslim","İstediğiniz zaman tam gün pakete yükseltme"]}},{"body":{"de":["Am Hochzeitstag ist selten Zeit für lange Portraits. Ein After-Wedding-Shooting löst das: zwei Stunden, ein Ort eurer Wahl – Weinberge, Schwarzwald, Bodensee oder eine Reise – und komplett ohne Zeitplan im Nacken."],"tr":["Düğün günü uzun portreler için nadiren zaman kalıyor. After-Wedding çekimi bunu çözüyor: iki saat, sizin seçtiğiniz bir yer – bağlar, Karaorman, Bodensee ya da bir seyahat – ve ensenizde program baskısı olmadan."]},"seed":"lum-service-after","slug":"after-wedding","short":{"de":"Noch einmal ins Kleid – ohne Zeitdruck, an einem Ort, den ihr euch aussucht.","tr":"Gelinliği bir kez daha giyin – zaman baskısı olmadan, seçtiğiniz bir yerde."},"title":{"de":"After-Wedding & Paarshooting","tr":"After-Wedding & Çift Çekimi"},"bullets":{"de":["2 Stunden reine Shootingzeit","Locationvorschläge inklusive","Auch als Reise-Shooting buchbar","40+ bearbeitete Bilder"],"tr":["2 saat net çekim","Mekân önerileri dahil","Seyahat çekimi olarak da mümkün","40+ düzenlenmiş kare"]}}],"marketing":{"pages":{"agb":{"image":"","title":{"de":"","tr":""},"noindex":false,"description":{"de":"","tr":""}},"home":{"image":"","title":{"de":"Hochzeitsfotograf Stuttgart – Foto & Video | Atelier Lumière","tr":"Stuttgart Düğün Fotoğrafçısı – Foto & Video | Atelier Lumière"},"noindex":false,"description":{"de":"Dokumentarische Hochzeitsfotografie und Hochzeitsfilm in Stuttgart, Ludwigsburg, Esslingen und Umgebung. Private Kundengalerie mit Album-Auswahl und digitale Hochzeitseinladung inklusive.","tr":"Stuttgart, Ludwigsburg, Esslingen ve çevresinde belgesel tarzda düğün fotoğrafçılığı ve düğün filmi. Albüm seçimli özel müşteri galerisi ve dijital düğün davetiyesi dahil."}},"preise":{"image":"","title":{"de":"Preise Hochzeitsfotograf Stuttgart – ab 690 €","tr":"Stuttgart düğün fotoğrafçısı fiyatları – 690 €\'dan"},"noindex":false,"description":{"de":"Transparente Pakete: Standesamt ab 690 €, Ganztagesreportage ab 1.890 €, Foto & Film ab 3.490 €. Anfahrt bis 60 km inklusive.","tr":"Şeffaf paketler: nikah 690 €\'dan, tam gün çekim 1.890 €\'dan, foto & film 3.490 €\'dan. 60 km\'ye kadar ulaşım dahil."}},"galerie":{"image":"","title":{"de":"Kundengalerie – Login","tr":"Müşteri galerisi – giriş"},"noindex":true,"description":{"de":"","tr":""}},"kontakt":{"image":"","title":{"de":"Kontakt – Hochzeitsfotograf Stuttgart anfragen","tr":"İletişim – Stuttgart düğün fotoğrafçısı"},"noindex":false,"description":{"de":"Fragt euer Hochzeitsdatum an. Antwort in der Regel innerhalb von 24 Stunden. Atelier in Stuttgart-Mitte.","tr":"Düğün tarihinizi sorun. Genelde 24 saat içinde yanıt. Atölye Stuttgart merkezde."}},"ratgeber":{"image":"","title":{"de":"Ratgeber – Hochzeitsfotografie, Zeitplan & Locations","tr":"Rehber – düğün fotoğrafçılığı, akış planı ve mekânlar"},"noindex":false,"description":{"de":"","tr":""}},"regionen":{"image":"","title":{"de":"Hochzeitsfotograf in Stuttgart & Umgebung – alle Regionen","tr":"Stuttgart ve çevresinde düğün fotoğrafçısı – tüm bölgeler"},"noindex":false,"description":{"de":"Stuttgart, Ludwigsburg, Esslingen, Böblingen, Heilbronn, Tübingen und mehr: Hochzeitsfotograf und Videograf mit Ortskenntnis – Anfahrt bis 60 km inklusive.","tr":"Stuttgart, Ludwigsburg, Esslingen, Böblingen, Heilbronn, Tübingen ve daha fazlası: bölgeyi tanıyan düğün fotoğrafçısı ve videografı – 60 km\'ye kadar ulaşım dahil."}},"einladung":{"image":"","title":{"de":"Digitale Hochzeitseinladung erstellen – mit RSVP & Countdown","tr":"Dijital düğün davetiyesi oluştur – RSVP ve geri sayımlı"},"noindex":false,"description":{"de":"Eigene Einladungsseite in drei Minuten: Countdown, Google-Maps-Route, WhatsApp-Versand und Zusagen. Für Hochzeitspaare von Atelier Lumière kostenlos.","tr":"Üç dakikada kendi davetiye sayfanız: geri sayım, Google Maps yol tarifi, WhatsApp paylaşımı ve katılım bildirimi. Atelier Lumière çiftlerine ücretsiz."}},"impressum":{"image":"","title":{"de":"","tr":""},"noindex":false,"description":{"de":"","tr":""}},"portfolio":{"image":"","title":{"de":"Portfolio – echte Hochzeiten aus Stuttgart & Region","tr":"Portfolyo – Stuttgart ve bölgeden gerçek düğünler"},"noindex":false,"description":{"de":"Vier Hochzeitsreportagen aus Stuttgart, Ludwigsburg und Fellbach – Schloss, Kelter und große Eventhalle.","tr":"Stuttgart, Ludwigsburg ve Fellbach\'tan dört düğün çekimi – saray, şaraphane ve büyük etkinlik salonu."}},"leistungen":{"image":"","title":{"de":"Leistungen – Hochzeitsfotografie & Hochzeitsfilm","tr":"Hizmetler – düğün fotoğrafçılığı & düğün filmi"},"noindex":false,"description":{"de":"Hochzeitsreportage, Hochzeitsfilm in 4K, Standesamt, Henna-Abend und After-Wedding-Shooting in Stuttgart und Umgebung.","tr":"Stuttgart ve çevresinde düğün çekimi, 4K düğün filmi, nikah, kına gecesi ve after-wedding çekimi."}},"ueber-mich":{"image":"","title":{"de":"","tr":""},"noindex":false,"description":{"de":"","tr":""}},"datenschutz":{"image":"","title":{"de":"","tr":""},"noindex":false,"description":{"de":"","tr":""}},"hochzeitslocations":{"image":"","title":{"de":"Hochzeitslocations Stuttgart & Region – Fotograf mit Ortskenntnis","tr":"Stuttgart ve çevresi düğün mekânları – mekânı tanıyan fotoğrafçı"},"noindex":false,"description":{"de":"Schloss, Festhalle, Eventlocation: Für die beliebtesten Hochzeitslocations der Region Stuttgart kennen wir Licht, Zeitplan und Hausregeln.","tr":"Saray, düğün salonu, etkinlik mekânı: Stuttgart bölgesinin en çok tercih edilen düğün mekânlarında ışığı, zaman planını ve kuralları biliyoruz."}}},"templates":{"city":{"de":"Hochzeitsfotograf {name} – Foto & Video ab 690 €","tr":"{name} Düğün Fotoğrafçısı – Foto & Video 690 €\'dan"},"post":{"de":"{title}","tr":"{title}"},"story":{"de":"{couple} – {venue}","tr":"{couple} – {venue}"},"venue":{"de":"{name} Hochzeitsfotograf – Erfahrung vor Ort","tr":"{name} düğün fotoğrafçısı – mekân tecrübesi"}},"defaultImage":""},"testimonials":[{"city":{"de":"Stuttgart","tr":"Stuttgart"},"name":"Elif & Marco","text":{"de":"Wir haben euch den ganzen Tag kaum bemerkt – und dann waren da 600 Bilder, auf denen alles drauf ist, was uns wichtig war.","tr":"Gün boyu sizi neredeyse fark etmedik – sonra bizim için önemli olan her şeyin olduğu 600 kare çıktı."}},{"city":{"de":"Fellbach","tr":"Fellbach"},"name":"Sarah & Daniel","text":{"de":"Die Online-Galerie war für unsere Familien perfekt. Meine Mutter in Izmir hat die Bilder am selben Abend gesehen.","tr":"Online galeri ailelerimiz için mükemmeldi. Annem İzmir\'de kareleri aynı akşam gördü."}},{"city":{"de":"Ludwigsburg","tr":"Ludwigsburg"},"name":"Aylin & Emre","text":{"de":"Der Film hat meinen Vater zum Weinen gebracht. Mehr muss man dazu nicht sagen.","tr":"Film babamı ağlattı. Daha fazla söze gerek yok."}}],"texts":{"home.heroEyebrow":{"de":"Hochzeitsfotografie & Film · Krumbach & Bayerisch-Schwaben","tr":"Düğün fotoğrafçılığı & film · Krumbach ve Bavyera-Suabya"},"home.heroText":{"de":"Dokumentarische Hochzeitsfotografie und Film in Krumbach, zwischen Ulm, Augsburg und dem Allgäu. Ruhig gearbeitet, ehrlich erzählt – und pünktlich geliefert.","tr":"Krumbach’ta, Ulm ile Augsburg ve Allgäu arasında belgesel tarzda düğün fotoğrafçılığı ve video. Sakin çalışılmış, dürüst anlatılmış – ve zamanında teslim edilmiş."},"home.citiesText":{"de":"Krumbach und 80 km Umkreis ohne Anfahrtskosten – von Günzburg und Ulm bis Augsburg und Memmingen. Für jede Stadt kennen wir Trauorte, Licht und Wege.","tr":"Krumbach ve 80 km çevresi yol ücretsiz – Günzburg ve Ulm’dan Augsburg ve Memmingen’e. Her şehir için nikâh yerlerini, ışığı ve yolları biliyoruz."},"footer.tagline":{"de":"Hochzeitsfotografie & Film in Krumbach und Bayerisch-Schwaben.","tr":"Krumbach ve Bavyera-Suabya’da düğün fotoğrafçılığı ve film."}},"themes":[{"id":"elysee","name":"Élysée","sub":{"de":"","tr":""},"bg":"#EFE7DC","paper":"#FBF6EE","paperEdge":"rgba(176,141,87,0.30)","fg":"#221C16","soft":"rgba(34,28,22,0.58)","accent":"#B08D57","accentSoft":"#D9C3A0","envelope":"#E8DCC9","envelopeFlap":"#E0D2BB","envelopeEdge":"rgba(176,141,87,0.45)","seal":"#B08D57","se